/**
 * upgrade 域升级链驱动：读刻度 → 取刻度仍停在起点的步骤 → 逐步执行并回写刻度 → 与插件版本对账。**任何一步失败即抛出，
 * 启动随之中止**（存储没升完就被按错误形态解释，比不启动糟得多）；步骤按**目标版本**排序执行，不按声明顺序。
 */
import type { LoggerPort } from "../../../shared/interface.ts";
import type { UpgradeDeps } from "../../deps.ts";
import { STEPS } from "../steps/index.ts";
import {
  compareVersions,
  pluginVersion,
  readStoredVersion,
  writeStoredVersion,
} from "../version/index.ts";
import type { UpgradeStep } from "./type.ts";

/**
 * 装配前跑一遍升级链（组合根在 `apply` 期调用）。必须在各域装配**之前**：升级会重写配置文件与存储文件，
 * 先装配就等于让各域先读到旧形态，再让它们带着旧形态继续跑。
 */
export function runUpgradeChain(deps: UpgradeDeps): void {
  const recorded = readStoredVersion();
  for (const step of pendingSteps(recorded)) applyStep(step, deps);
  reportGap(readStoredVersion(), pluginVersion(), deps.logger);
}

/** 刻度还停在这一步起点或更早的步骤，按目标版本升序。 */
function pendingSteps(recorded: string): UpgradeStep[] {
  return [...STEPS]
    .sort((left, right) => compareVersions(left.targetVersion, right.targetVersion))
    .filter((step) => compareVersions(step.fromVersion, recorded) >= 0);
}

/**
 * 执行一步，成功后回写刻度。回写在 `run` 之后而不是之前：刻度是「这一步做完了」的凭证，先写刻度等于把凭证
 * 发给一件还没做完的事。失败时抛出的错误带上目标版本，是为了让「哪一步」出现在启动失败的现场。
 */
function applyStep(step: UpgradeStep, deps: UpgradeDeps): void {
  try {
    step.run(deps);
  } catch (cause) {
    throw new Error(
      `dsh-notifier: 存储升级到 ${step.targetVersion} 失败 — ${cause instanceof Error ? cause.message : "未知原因"}`,
      { cause },
    );
  }
  const written = writeStoredVersion(step.targetVersion);
  if (!written.ok) {
    throw new Error(`dsh-notifier: 存储版本号回写失败（${step.targetVersion}）— ${written.reason}`);
  }
}

/**
 * 链跑完后的对账（导出只为本域用例能直接喂 (recorded, target) 断言三种落差；对外契约面仍只有 `installUpgrade`）。
 * 三种落差分开报，因为它们要人去改的地方完全不同：落后 = 这一步的升级函数还没写（开发期
 * 漏项）；超前且步骤表本身也超前 = 步骤表与 package.json 没同步；超前而步骤表没超前 = 装的是更旧的包（降级）。
 * 三者都不中止启动——它们不是迁移动作失败，而静默地把刻度改成看起来对的值更糟。
 */
export function reportGap(recorded: string, target: string, logger: LoggerPort): void {
  const gap = compareVersions(recorded, target);
  if (gap === 0) return;

  if (gap < 0) {
    logger.warn(`dsh-notifier: 存储版本 ${recorded} 落后于插件版本 ${target}，缺少对应的升级步骤`);
    return;
  }

  const newest = newestTargetVersion();
  if (newest !== "" && compareVersions(newest, target) > 0) {
    logger.warn(
      `dsh-notifier: 升级链的目标版本 ${newest} 高于插件版本 ${target}（存储已升到 ${recorded}）——步骤表与 package.json 不同步`,
    );
    return;
  }
  logger.warn(`dsh-notifier: 存储版本 ${recorded} 高于插件版本 ${target}，本插件的升级链不回退`);
}

/** 步骤表里最高的目标版本；空表时给空串。 */
function newestTargetVersion(): string {
  let newest = "";
  for (const step of STEPS) {
    if (newest === "" || compareVersions(step.targetVersion, newest) > 0)
      newest = step.targetVersion;
  }
  return newest;
}

/** upgrade 域存量配置的读取（0.2.3 及更早）：**V1** 是 0.2.3 搬进官方 settings 命名空间的那份，**V0** 是更早的自建
 * JSON 文件（0.2.3 迁移时改名成 `…migrated.bak` 作幂等标记）。**V1 优先于 V0**——反过来取会让「设置回到更早的样子」。
 *
 * V1 从**宿主文档文件**直接读：`describe()` 只列已注册的命名空间，而本插件不再注册它（见 `type.ts` 的说明），
 * 服务面那条路读不到存量的 user 层——把它留在后面只作非文件型 provider 的兜底。 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import { dshHome } from "../../../../../../../shared/dsh-home.js";
import { legacyFile } from "../../../shared/interface.ts";
import type { RawSettingValue } from "../../deps.ts";
import type { LegacySettingsFace, LegacyStoredSettings } from "./type.ts";

/** 本插件在官方 settings 服务里的命名空间（0.2.3 用的那个）。 */
const SETTINGS_NS = "dsh-notifier";

/** settings 文档的候选文件名：`.yaml` 是官方文件型 provider 的缺省，`.json` 是它支持的另一种扩展名。
 * 名字与位置都是**宿主**的约定、本包只在割接时读一次，不属本包存储布局，故随本块而不进共享层。 */
const SETTINGS_DOC_FILES: readonly string[] = ["settings.yaml", "settings.json"];

/** V0 的两个候选文件名，按优先级。`…migrated.bak` 是 0.2.3 迁移完成后改的名，内容与改名前的 json 逐字相同，所以
 * 「json 在就用 json、不在就用 bak」不会在两者之间做出错误取舍。 */
const LEGACY_FILES: readonly string[] = ["dsh-notifier.json", "dsh-notifier.json.migrated.bak"];

/** 旧配置里属于组合层装配的键：新架构下它们是启动参数（挂载点传入），不再进配置文件——留在配置里会被读成用户显式
 * 设置过的值，而它们在设置页上根本无处可改。 */
const ENTRY_KEYS: readonly string[] = [
  "enabled",
  "configFile",
  "historyFile",
  "statusFile",
  "toastScript",
];

/** 旧的全局声音开关；新架构按出口拆成两个键。 */
const LEGACY_SOUND_KEY = "notifySound";

/** 两个按出口的声音键：旧键有值而它们缺失时按旧键补齐，让用户原来的选择不作废。 */
const SOUND_KEYS: readonly string[] = ["browserSound", "systemSound"];

/** 原型链上的危险键名：JSON 文本能造出自有键，展开进设置对象就会改写原型。与 config 域写面同一份口径——
 * 这几条在写面本来就进不来，迁移更不该把它们搬进新配置。 */
const UNSAFE_KEYS: readonly string[] = ["__proto__", "constructor", "prototype"];

/** 读存量设置：V1（宿主文档文件 → 已注册命名空间）优先，回退 V0。
 * @returns 已做语义转换的设置；空对象 = 旧版本没有可迁的东西，它同时是「读不到」与「读到了但一个键都没有」的答案。 */
export function readLegacySettings(settings: LegacySettingsFace): LegacyStoredSettings {
  const fromDocument = readFromDocument(documentPathOf(settings));
  if (Object.keys(fromDocument).length > 0) return fromDocument;
  const fromSettings = readFromSettings(settings);
  if (Object.keys(fromSettings).length > 0) return fromSettings;
  return readFromFile();
}

/** provider 自报的文档路径。它由 provider 实现（文件型 provider 是个 getter），取它本身就可能在对方那一侧失败——
 * 与 `describe()` 同形按「没有文件」处理：读存量不该因为 provider 的实现问题拦住插件启动。 */
function documentPathOf(settings: LegacySettingsFace): string | undefined {
  try {
    return settings.documentPath;
  } catch {
    return undefined;
  }
}

/**
 * 读宿主 settings 文档里本插件那一节（V1 的原始 user 层）。
 *
 * 为什么不问服务要：`describe()` 只列已注册的命名空间，而本插件从 0.2.4 起不再注册它——那条路永远读空。
 * `documentPath` 由 provider 自报（文件型 provider 覆盖了该 getter），拿不到就按官方缺省名在 DSH home 下找。
 */
function readFromDocument(documentPath: string | undefined): LegacyStoredSettings {
  for (const path of documentCandidates(documentPath)) {
    const section = readDocumentSection(path);
    if (section !== undefined) return convert(section);
  }
  return {};
}

/** 候选文档路径：provider 自报的优先；它没有文件（或没给出路径）时按官方缺省名在 DSH home 根下找——非文件型
 * provider 读不到，也就自然落到下一环（服务面）。 */
function documentCandidates(documentPath: string | undefined): readonly string[] {
  if (typeof documentPath === "string" && documentPath.trim().length > 0) return [documentPath];
  return SETTINGS_DOC_FILES.map((name) => join(dshHome(), name));
}

/** 读一份文档并取本插件的分节：文件不存在、读不动、解析失败、分节不是普通对象、分节序列化不了，一律算「没有存量」。 */
function readDocumentSection(path: string): LegacyStoredSettings | undefined {
  if (!existsSync(path)) return undefined;
  let text: string;
  try {
    text = readFileSync(path, "utf8");
  } catch {
    // 权限或竞态：读存量不该拦住插件启动，按没有存量处理。
    return undefined;
  }
  const document = parseDocumentText(text, path);
  const section = document === undefined ? undefined : document[SETTINGS_NS];
  if (section === undefined) return undefined;
  if (!isPlainRecord(section)) return undefined;
  // YAML 别名能造出循环引用，而割接最终要把存量序列化进 config.json：序列化不了的分节按读不动处理（回退下一环），
  // 而不是让落盘时的 TypeError 把这次装配拖下水。
  return isSerializable(section) ? section : undefined;
}

/** 存量最终要经 `JSON.stringify` 落进 config.json——能不能序列化，是它作为「可搬迁存量」的准入条件。 */
function isSerializable(raw: RawSettingValue): boolean {
  try {
    JSON.stringify(raw);
    return true;
  } catch {
    return false;
  }
}

/** 按扩展名分派解析：`.json` 用 JSON，其余按 YAML（官方 provider 只认 .yaml / .yml / .json）；坏文本算解释不了。 */
function parseDocumentText(
  text: string,
  path: string,
): Record<string, RawSettingValue> | undefined {
  try {
    const parsed: RawSettingValue = path.endsWith(".json") ? JSON.parse(text) : parseYaml(text);
    return isPlainRecord(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

/** 普通对象判定：数组与 null 都能被 `Object.keys` 读出一堆假键，认下来就等于往配置里灌用户从没设过的键。 */
function isPlainRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/** 读官方 settings 里那个命名空间的 user 层（兜底：只有**已注册**该命名空间的 provider 才会命中）。 */
function readFromSettings(settings: LegacySettingsFace): LegacyStoredSettings {
  let entries: ReturnType<LegacySettingsFace["describe"]>;
  try {
    entries = settings.describe({ redactSecrets: true });
  } catch {
    // 服务在，但它拒绝了这次调用（版本不匹配、内部错误）：读存量不该拦住插件启动，
    // 报错就在这里结束。
    return {};
  }
  for (const entry of entries) {
    if (entry.ns !== SETTINGS_NS) continue;
    // settings 对自己的 `user` 只承诺「有值」，形状判断归读它的人：不是普通对象就按没有存量处理。
    const user = entry.user;
    if (typeof user !== "object" || user === null || Array.isArray(user)) return {};
    return convert(user as LegacyStoredSettings);
  }
  return {};
}

/** 读 V0 文件；第一个能解释的名字胜出，全都读不出来就是空。 */
function readFromFile(): LegacyStoredSettings {
  for (const name of LEGACY_FILES) {
    const path = legacyFile(name);
    if (!existsSync(path)) continue;
    try {
      const raw: RawSettingValue = JSON.parse(readFileSync(path, "utf8"));
      if (!isPlainRecord(raw)) continue;
      return convert(raw);
    } catch {
      // 损坏：换下一个候选。原地保留文件——用户可能还想手工看看里面是什么。
      continue;
    }
  }
  return {};
}

/** 旧配置语义 → 当前配置语义：剔掉装配键、把旧的全局声音键摊到两个出口键上。契约不认识的键**原样保留**——它们可能
 * 是用户手写的、也可能是更高版本留下的，迁移没有资格替他们决定哪些该丢；原型链上的危险键名除外，它们在写面本来
 * 就进不来（config 域同一份口径），搬过去只会让读出来的对象带上一个别人给的原型。 */
function convert(stored: LegacyStoredSettings): LegacyStoredSettings {
  const next: Record<string, RawSettingValue> = {};
  for (const key of Object.keys(stored)) {
    if (ENTRY_KEYS.includes(key) || UNSAFE_KEYS.includes(key)) continue;
    next[key] = stored[key];
  }
  const legacySound = next[LEGACY_SOUND_KEY];
  if (typeof legacySound === "boolean") {
    for (const key of SOUND_KEYS) {
      if (!(key in next)) next[key] = legacySound;
    }
  }
  return next;
}

/** upgrade 域版本号与版本文件：**存储版本**（`version` 文件里的刻度）与**插件版本**（package.json 里的目标）在这里
 * 相遇，升级链就是把前者逐刻度推到后者——两者分开存放，才区分得开「还没升」与「升完了」。 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  readTextFileSync,
  writeTextAtomicSync,
  VERSION_FILE_NAME,
  notifierFile,
  type FileWrite,
} from "../../../shared/interface.ts";

/** 没有版本文件时的起点：从未升级过。 */
const BASELINE_VERSION = "0.0.0";

/** 取不到插件版本时的兜底。读到包清单失败不该阻断启动——升级链空转一轮而已。 */
const UNKNOWN_VERSION = "0.0.0";

/** 读存储版本。没有版本文件 = 从未升级过 = 从零跑整条链：每一步都会自己判断有没有它的活要干，全新安装下全部空转，
 * 而从更早版本升上来的安装正好借这一轮把该做的做掉。 */
export function readStoredVersion(): string {
  const read = readTextFileSync(notifierFile(VERSION_FILE_NAME));
  if (!read.ok) return BASELINE_VERSION;
  const text = read.text.trim();
  return text === "" ? BASELINE_VERSION : text;
}

/** 写存储版本：一步升级完成即推进一档；写不进去就停在原处，下次重跑该步。 */
export function writeStoredVersion(version: string): FileWrite {
  return writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), `${version}\n`);
}

/** 本插件当前版本：读包根的 package.json。不写成常量——常量与发布版本之间没有任何机制保证同步，而漂移的那一次会让
 * 升级链永远停在旧刻度上（「版本没变」与「升级没做完」外部表现一模一样）。路径按**产物形态**取：tsc 产物经
 * bundle-host 全部内联进 `lib/index.js`，故本模块运行时所在目录就是 `lib/`，包根在上一级。 */
export function pluginVersion(): string {
  try {
    const manifest = join(dirname(fileURLToPath(import.meta.url)), "..", "package.json");
    const parsed: { version?: string } = JSON.parse(readFileSync(manifest, "utf8"));
    return typeof parsed.version === "string" ? parsed.version : UNKNOWN_VERSION;
  } catch {
    return UNKNOWN_VERSION;
  }
}

/** 版本号比较：逐段数值比较。段数不同按缺位补零（`0.3` 等价 `0.3.0`）；预发布后缀（`-rc.1`）不参与比较——本包的
 * 版本序列只用到 `主.次.修订`，为一个不会出现的输入引一套 semver 语义，换来的是又一处需要跟着上游走的依赖。 */
export function compareVersions(left: string, right: string): number {
  const a = parseVersion(left);
  const b = parseVersion(right);
  const length = Math.max(a.length, b.length);
  for (let index = 0; index < length; index += 1) {
    const difference = (a[index] || 0) - (b[index] || 0);
    if (difference !== 0) return difference > 0 ? 1 : -1;
  }
  return 0;
}

function parseVersion(text: string): number[] {
  return text.split(".").map((part) => Number.parseInt(part, 10) || 0);
}

/** upgrade 域生命周期：装配期同步跑完升级链。链动的是磁盘上的文件（存储三个文件 + 配置文件的形态割接），
 * 存量配置的读取面由组合根以显式依赖注入，装配期即可同步读——不再有「等宿主服务就绪」那段回调。 */
import type { UpgradeDeps } from "../../deps.ts";
import { runUpgradeChain } from "../chain/index.ts";

/** 升级域：装配期一次，此后没有活要干。 */
class UpgradeRunner {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;

  /** 装配：先跑链。链在标记装配完成之前跑——它抛错时这次装配等于没发生，宿主重试装配才有机会重跑链（链是幂等的）。 */
  install(deps: UpgradeDeps): void {
    if (this.installed) throw new Error("dsh-notifier: upgrade 域只能装配一次");
    runUpgradeChain(deps);
    this.installed = true;
  }

  /** 卸载：本域没有需要释放的东西——它只写了文件。 */
  release(): void {
    this.installed = false;
  }
}

/** 本域唯一的装配实例：类不外放，外面 `new` 不出第二份升级流程。 */
export const upgradeRunner = new UpgradeRunner();

/**
 * upgrade 域 0.2.3 → 0.2.4：配置形态割接——把散在顶层的渠道开关搬进 `channels` 数组的两条内置条目。
 *
 * 为什么直接读写文件而不是走 config 域的写面：链跑在各域装配**之前**，那时写面没有装配好的配置镜像，
 * 以它当基底合并会把整份配置写空。本步只做结构搬运——读出来、换个位置、写回去——不解释语义，所以
 * 「什么算合法设置」仍旧只有 config 域归一化一个答案；它装配在本步之后，读到的正是割接后的形态。
 *
 * 幂等：条目已在场且没有存量要合并时直接返回，重跑与首次跑的结果逐字相同。
 */
import {
  readTextFileSync,
  writeTextAtomicSync,
  CONFIG_FILE_NAME,
  notifierFile,
} from "../../../shared/interface.ts";
import type { LegacySettingsFace, RawSettingValue } from "../../deps.ts";
import { readLegacySettings } from "../legacy/index.ts";

/**
 * 内置频道类型。这里是**升级域的清单**（旧格式里哪两个渠道要收进 `channels`），不是 config 域那份的
 * 副本：本域不认识当前设置的形状，只认识「旧文件里有哪几个顶层键、该把它们搬到哪儿」。
 */
const BUILTIN_TYPES = ["browser", "system"] as const;

/**
 * 0.2.3 及更早的顶层渠道键：值搬进内置条目之后**删除**——迁移一次做完，不留「旧键还能读」的第二处表达。
 * 读面（config 域归一化）仍能在未割接的文件上消费这些键，所以即便这一步没跑到，行为也不会退化。
 */
const RETIRED_KEYS: readonly string[] = [
  "systemEnabled",
  "browserEnabled",
  "systemNotify",
  "browserNotify",
  "notifyWhenVisible",
  "notifySound",
  "browserSound",
  "systemSound",
];

type BuiltinType = (typeof BUILTIN_TYPES)[number];

/**
 * 割接：宿主 settings 里的存量与当前配置文件合并，再把顶层渠道键搬进两条内置条目。
 *
 * 合并顺序与旧写面同口径（文件为基底、存量覆盖）：「设置回到更早的样子」比「保留当前值」糟得多。
 */
export function migrateConfigShape(settings: LegacySettingsFace): void {
  const file = notifierFile(CONFIG_FILE_NAME);
  const read = readTextFileSync(file);
  const stored = read.ok ? parseObject(read.text) : {};
  const legacy = readLegacySettings(settings);
  const hasLegacy = Object.keys(legacy).length > 0;
  // 既没有文件内容也没有存量 = 全新安装：默认表就是它的形态，凭空建一份文件反而会让设置页把默认值
  // 标成「用户改过」——那正是「文件里每个键都被读成显式提交」这条既有语义的反面。
  if (!hasLegacy && Object.keys(stored).length === 0) return;
  const merged: Record<string, RawSettingValue> = { ...stored, ...legacy };
  const shaped = withBuiltinChannels(merged);
  // 有存量就必须落盘（合并结果与文件不同）；没有存量时只在真的缺内置条目时才写。
  if (!hasLegacy && shaped === null) return;
  const written = writeTextAtomicSync(file, `${JSON.stringify(shaped ?? merged, null, 2)}\n`);
  if (!written.ok) throw new Error(`dsh-notifier: 配置形态割接落盘失败 — ${written.reason}`);
}

/** 割接后的形态；`null` = 没有可搬的键、也没有可删的键（幂等出口）。 */
function withBuiltinChannels(
  stored: Record<string, RawSettingValue>,
): Record<string, RawSettingValue> | null {
  const list = Array.isArray(stored.channels) ? stored.channels : [];
  const present = new Set<RawSettingValue>();
  for (const item of list) {
    if (isRecord(item)) present.add(item.type);
  }
  const missing = BUILTIN_TYPES.filter((type) => !present.has(type));
  const retired = RETIRED_KEYS.filter((key) => stored[key] !== undefined);
  if (missing.length === 0 && retired.length === 0) return null;
  // 内置恒在最前：与 config 域归一化后的顺序一致，用户看到的卡片顺序不会因为割接而变。
  const next: Record<string, RawSettingValue> = {
    ...stored,
    channels: [...missing.map((type) => builtinEntry(stored, type)), ...list],
  };
  // 搬完即删：同一个事实不留两处表达——留着旧键就成了下一个 `notifySound` 式的隐患。
  for (const key of retired) delete next[key];
  return next;
}

/** 内置条目：只搬**有值**的存量键，缺的留给 config 域归一化补默认——割接不替用户决定默认值。 */
function builtinEntry(
  stored: Record<string, RawSettingValue>,
  type: BuiltinType,
): Record<string, RawSettingValue> {
  const entry: Record<string, RawSettingValue> = { type, id: type };
  const fields: ReadonlyArray<readonly [string, RawSettingValue]> =
    type === "browser"
      ? [
          ["enabled", stored.browserEnabled],
          ["popup", stored.browserNotify],
          ["sound", firstDefined(stored.browserSound, stored.notifySound)],
          ["whenVisible", stored.notifyWhenVisible],
        ]
      : [
          ["enabled", stored.systemEnabled],
          ["popup", stored.systemNotify],
          ["sound", firstDefined(stored.systemSound, stored.notifySound)],
        ];
  for (const [key, value] of fields) {
    if (value !== undefined) entry[key] = value;
  }
  return entry;
}

/** 存量音效键的取值顺序：按出口的键优先，其次旧的全局键——与 config 域归一侧同序，两处不能各说各话。 */
function firstDefined(outlet: RawSettingValue, legacy: RawSettingValue): RawSettingValue {
  return outlet === undefined ? legacy : outlet;
}

/** 文件内容 → 对象；坏 JSON 与非对象都当「没有配置」——一份读不动的文件不该让启动失败。 */
function parseObject(text: string): Record<string, RawSettingValue> {
  try {
    const parsed: RawSettingValue = JSON.parse(text);
    return isRecord(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/** upgrade 域升级链的步骤表。**新增版本时必须在此追加一项**，哪怕这一步没有数据要改（`run` 给空实现）：链的推进
 * 以步骤为刻度，漏掉的版本会让存储刻度永久停在旧值上。 */
import type { UpgradeDeps } from "../../deps.ts";
import type { UpgradeStep } from "../chain/type.ts";
import { migrateConfigShape } from "./config-shape.ts";
import { migrateReasonShape } from "./reason-shape.ts";
import { migrateStorageLayout } from "./storage-layout.ts";

/** 0.2.3 → 0.2.4：存储布局归位 + 配置形态割接 + 投递理由形态割接——同一次版本迁移的三半，合成一步。 */
function migrateToNewLayout(deps: UpgradeDeps): void {
  // 顺序有意义：布局归位先建出新位置的初始形态，理由割接才有文件可读（旧位置的文件已被搬走）。
  migrateStorageLayout();
  migrateConfigShape(deps.legacySettings);
  migrateReasonShape();
}

/** 按目标版本升序维护；执行顺序由链驱动排序决定，此处顺序只为便于阅读。 */
export const STEPS: readonly UpgradeStep[] = [
  { fromVersion: "0.2.3", targetVersion: "0.2.4", run: migrateToNewLayout },
];

/**
 * upgrade 域 0.2.3 → 0.2.4：投递理由形态割接——`status.json` 与 `history.jsonl` 里存的是散文，
 * 之后存结构化对象（`{ code, params?, detail? }`）。
 *
 * 为什么放在升级链里而不是让读面各判一次：这两个文件都是**整份重写**的存储，割接一次之后磁盘上
 * 只剩一种形态，客户端不必为「同一字段两种形态」写两遍渲染。读面留下的值域校验只兜手改与半截
 * 写入，不再承担「历史形态」这条主线。
 *
 * 幂等：已经是结构化对象的条目原样保留，重跑不叠加。**解析不出内容时不动那个文件**——两个存储
 * 的读面本来就容错（坏行跳过、半截 JSON 从空表开始），为一份读不出的旧文件拦住启动是更坏的结果；
 * 而写失败必须抛出，那才是「迁移没做完」（与 storage-layout 同一口径）。
 */
import { readFileSync } from "node:fs";
import {
  writeTextAtomicSync,
  HISTORY_FILE_NAME,
  STATUS_FILE_NAME,
  normalizeReason,
  notifierFile,
  sameReasonShape,
} from "../../../shared/interface.ts";

/** 形态割接的落点：文件名 + 一份「把一条记录里嵌的理由挑出来重写」的转换。 */
export function migrateReasonShape(): void {
  rewriteFile(notifierFile(STATUS_FILE_NAME), migrateStatusText);
  rewriteFile(notifierFile(HISTORY_FILE_NAME), migrateHistoryText);
}

/**
 * 读 → 转换 → 有变化才写回。
 *
 * 「只在有变化时写」不是省一次 IO：`history.jsonl` 是追加式存储，无条件重写在并发 append 时
 * 会把那一行盖掉；没有旧形态可割接时什么都不碰，是唯一不引入新竞争窗口的形态。
 */
function rewriteFile(file: string, transform: (text: string) => string | undefined): void {
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch {
    // 文件不存在：storage-layout 已经建出初始形态，这里没有活要干。
    return;
  }
  const migrated = transform(text);
  if (migrated === undefined || migrated === text) return;
  const written = writeTextAtomicSync(file, migrated);
  if (!written.ok) throw new Error(`投递理由割接写入失败：${file} — ${written.reason}`);
}

/** `status.json`：逐条把 `lastError` 的旧散文形态换成结构化理由，其余字段原样保留。 */
function migrateStatusText(text: string): string | undefined {
  const table = parseObject(text);
  if (table === undefined) return undefined;
  let changed = false;
  const rebuilt: Record<string, unknown> = {};
  for (const [channelId, entry] of Object.entries(table)) {
    const migrated = migrateStatusEntry(entry);
    if (migrated !== entry) changed = true;
    rebuilt[channelId] = migrated;
  }
  return changed ? `${JSON.stringify(rebuilt, null, 2)}\n` : undefined;
}

/** 单条状态：只认「有 lastError 且它不是规范化后的形态」这一种需要动的形状，其余原样返回。 */
function migrateStatusEntry(entry: unknown): unknown {
  if (typeof entry !== "object" || entry === null || Array.isArray(entry)) return entry;
  const source = entry as Record<string, unknown>;
  if (source.lastError === undefined) return entry;
  const reason = normalizeReason(source.lastError);
  if (reason === undefined) return entry;
  // 已经是同一个对象级形态（`normalizeReason` 对结构化输入是恒等语义的）就不再重写。
  if (sameReasonShape(source.lastError, reason)) return entry;
  return { ...source, lastError: reason };
}

/** `history.jsonl`：逐行换掉 `channels[].reason`，坏行原样保留（读侧本来就跳过它）。 */
function migrateHistoryText(text: string): string | undefined {
  let changed = false;
  const lines = text.split("\n").map((line) => {
    if (line === "") return line;
    const migrated = migrateHistoryLine(line);
    if (migrated === undefined) return line;
    changed = true;
    return migrated;
  });
  return changed ? lines.join("\n") : undefined;
}

function migrateHistoryLine(line: string): string | undefined {
  const entry = parseObject(line);
  if (entry === undefined) return undefined;
  const channels = entry.channels;
  if (!Array.isArray(channels)) return undefined;
  let changed = false;
  const rebuilt = channels.map((delivery) => {
    if (typeof delivery !== "object" || delivery === null || Array.isArray(delivery))
      return delivery;
    const source = delivery as Record<string, unknown>;
    if (source.reason === undefined) return delivery;
    const reason = normalizeReason(source.reason);
    if (reason === undefined || sameReasonShape(source.reason, reason)) return delivery;
    changed = true;
    return { ...source, reason };
  });
  return changed ? JSON.stringify({ ...entry, channels: rebuilt }) : undefined;
}

/** 解析成 JSON 对象；数组、标量、坏 JSON 都算读不出（调用点按此跳过而不是猜）。 */
function parseObject(text: string): Record<string, unknown> | undefined {
  try {
    const parsed = JSON.parse(text) as unknown;
    return typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

/**
 * upgrade 域 0.2.3 → 0.2.4：存储布局归位——把散在 DSH home 根目录的数据文件收进包私有目录；**没有旧文件的安装同样
 * 在这一步落定**（直接建出初始形态）。配置文件不在这里：它有两代旧形态，读取要等宿主服务就绪（装配期拿不到的时机）。
 */
import { existsSync, readFileSync, renameSync } from "node:fs";
import {
  writeTextAtomicSync,
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  legacyFile,
  notifierFile,
} from "../../../shared/interface.ts";
/** 旧文件改名后缀：搬完留证据，也是「这一份处理过了」的标记。 */
const MIGRATED_SUFFIX = ".migrated.bak";

/** 空 JSON 对象的落盘形态。 */
const EMPTY_OBJECT = "{}\n";

/** 序号文件的初始形态：与流侧落盘同形（流侧写 `${seq}\n`），首次读取直接得到 0。 */
const ZERO_SEQ = "0\n";

/** 存储布局的一项。 */
interface StorageEntry {
  /** 旧文件名（DSH home 根目录下）。 */
  legacy: string;
  /** 新文件名（包私有存储目录下）。 */
  target: string;
  /** 目标缺失且无旧文件时的初始形态。 */
  initial: string;
}

const LAYOUT: readonly StorageEntry[] = [
  {
    legacy: "dsh-notifier-history.jsonl",
    target: HISTORY_FILE_NAME,
    initial: "",
  },
  {
    legacy: "dsh-notifier-status.json",
    target: STATUS_FILE_NAME,
    initial: EMPTY_OBJECT,
  },
  {
    legacy: "notifier-seq.json",
    target: SEQ_FILE_NAME,
    initial: ZERO_SEQ,
  },
];

/**
 * 旧存储 → 新存储布局：有旧文件的搬过来，没有的建出初始形态。初始形态一律是**空结构**而不是默认值快照
 * ——写全量默认值会把「用户覆盖过哪些键」这个语义冲掉（文件里每个键都会被读成用户显式提交的），而那份差别
 * 正是设置页判断哪些字段该标记为「已改」的依据。逐文件独立（一个搬不动不影响其余），但**搬不动都抛出**：
 * 迁移没做完而启动照常，等于让各域按错误的形态去读数据。幂等：目标已存在即处理过，归档名固定、重跑不累积。
 */
export function migrateStorageLayout(): void {
  for (const entry of LAYOUT) settleOne(entry);
}

/**
 * 落定一项。目标已存在即视为「这一份处理过了」：不覆盖、只把源文件归档——用户可能在新位置已经改过东西，
 * 用旧文件盖回去等于用历史覆盖现在。
 */
function settleOne(entry: StorageEntry): void {
  const target = notifierFile(entry.target);
  const source = legacyFile(entry.legacy);

  if (existsSync(target)) {
    archive(source, MIGRATED_SUFFIX);
    return;
  }
  if (!existsSync(source)) {
    writeTarget(target, entry.initial);
    return;
  }
  writeTarget(target, readSource(source));
  archive(source, MIGRATED_SUFFIX);
}

/** 读旧文件；读不出来即抛——那是「搬不动」，不该被当成「没有旧数据」。 */
function readSource(source: string): string {
  try {
    return readFileSync(source, "utf8");
  } catch (cause) {
    throw new Error(`旧存储文件不可读：${source}`, { cause });
  }
}

function writeTarget(target: string, text: string): void {
  const written = writeTextAtomicSync(target, text);
  if (!written.ok) throw new Error(`存储文件落盘失败：${target} — ${written.reason}`);
}

/** 归档旧文件；本来就没有就什么都不做。后缀是「这一份处理过了」的标记。 */
function archive(source: string, suffix: string): void {
  if (!existsSync(source)) return;
  try {
    renameSync(source, `${source}${suffix}`);
  } catch (cause) {
    throw new Error(`旧存储文件改名失败：${source}`, { cause });
  }
}

