/**
 * dsh-notifier upgrade 域 legacy 块 —— 存量设置的读取（V1：宿主 settings 文档 / 服务面，V0：自建 JSON 文件）。
 *
 * 判据面：这一块决定升级后用户看到的是**哪一份设置**。取错顺序（V0 盖 V1）或漏做语义转换的表现都是
 * 「升级后设置回到了更早的样子」，而磁盘上一切正常、没有任何报错。故这里逐条锁优先级与转换规则。
 *
 * 一条专门的判据面：**未注册命名空间也要读得到**（`describe()` 只列已注册的，而本插件不再注册它）。
 */
import { existsSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { legacyFile } from "../../../src/server/shared/interface.ts";
import { readLegacySettings } from "../../../src/server/upgrade/impl/legacy/index.ts";
import type { LegacySettingsFace } from "../../../src/server/upgrade/impl/legacy/type.ts";
import { tempDshHome, wire } from "../../helpers.ts";

/** 本插件 0.2.3 在官方 settings 服务里用的命名空间。 */
const NS = "dsh-notifier";

/**
 * 假描述符：本域只读 `ns` 与 `user` 两项，官方描述符的其余字段（schema / revision / applies）
 * 与判据无关，也就没必要在这里拼出来——拼一份假的反倒成了第二个事实源。
 */
type FakeDescriptor = { ns: string; user?: unknown };

/** settings 的描述选项：只关心脱敏开关，其余键不参与判据。 */
type FakeDescribeOptions = { redactSecrets?: boolean };

let home: { readonly dir: string; dispose: () => void };

beforeEach(() => {
  home = tempDshHome();
});

afterEach(() => {
  home.dispose();
});

/** 假 settings 读面：`describe` 给固定条目（或按需抛错），`documentPath` 指向宿主文档（缺省 = provider 没有文件）。 */
function makeSettings(
  entries: readonly FakeDescriptor[],
  throws = false,
  documentPath?: string,
): LegacySettingsFace {
  return {
    describe: () => {
      if (throws) throw new Error("settings 服务拒绝了这次调用");
      return entries as unknown as ReturnType<LegacySettingsFace["describe"]>;
    },
    documentPath,
  };
}

/** 写一份宿主 settings 文档（默认 YAML 形态，与官方文件型 provider 一致）。 */
function writeDocument(text: string, name = "settings.yaml"): string {
  const path = join(home.dir, name);
  writeFileSync(path, text, "utf8");
  return path;
}

/** 写一份 V0 配置文件（旧的自建 JSON）。 */
function writeLegacyFile(name: string, body: unknown): void {
  writeFileSync(legacyFile(name), typeof body === "string" ? body : JSON.stringify(body), "utf8");
}

describe("读取优先级：V1 优先，V0 兜底", () => {
  it("settings 里有本插件命名空间时无视 V0 文件（反过来取会让设置回到更早的样子）", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });
    const settings = makeSettings([{ ns: NS, user: { notifyAsk: false } }]);
    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
  });

  it("settings 里没有本插件命名空间时回退 V0 文件", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });
    const settings = makeSettings([{ ns: "other-plugin", user: { notifyAsk: false } }]);
    expect(readLegacySettings(settings)).toEqual({ notifyAsk: true });
  });

  it("V1 条目存在但 user 不是对象时同样回退 V0 文件（脏条目不能把存量配置吃掉）", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });
    // 数组只是脏的一种：标量（typeof 不是 object）与 null（typeof 是 object 但取键会抛）都要挡住。
    for (const user of [["notifyAsk"], "notifyAsk", 42, wire<FakeDescriptor["user"]>(null)]) {
      expect(readLegacySettings(makeSettings([{ ns: NS, user }]))).toEqual({ notifyAsk: true });
    }
  });

  it("读服务面时要求脱敏（脱敏开关只管服务面出口；文档那条路拿到的本来就是原文）", () => {
    const calls: Array<FakeDescribeOptions | undefined> = [];
    const settings: LegacySettingsFace = {
      describe: (options) => {
        calls.push(options);
        return [{ ns: NS, user: { notifyAsk: false } }] as unknown as ReturnType<
          LegacySettingsFace["describe"]
        >;
      },
      documentPath: undefined,
    };

    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
    expect(calls).toEqual([{ redactSecrets: true }]);
  });

  it("settings 调用抛错时回退 V0 文件（服务在但拒绝这次调用，不该拦住插件启动）", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });
    expect(readLegacySettings(makeSettings([], true))).toEqual({ notifyAsk: true });
  });

  it("V0 的第二个候选名在 json 缺失时生效（0.2.3 迁移把 json 改名成 .migrated.bak，内容逐字相同）", () => {
    writeLegacyFile("dsh-notifier.json.migrated.bak", { notifyAsk: false });
    expect(readLegacySettings(makeSettings([]))).toEqual({ notifyAsk: false });
  });

  it("V0 文件损坏时给空对象并原地保留文件（用户可能还想手工看看里面是什么）", () => {
    writeLegacyFile("dsh-notifier.json", "{ 这不是 JSON");
    expect(readLegacySettings(makeSettings([]))).toEqual({});
    expect(existsSync(legacyFile("dsh-notifier.json"))).toBe(true);
  });

  // 合法 JSON 但不是对象：数组/标量都能被 Object.keys 读出一堆下标键，认下来就等于往配置里
  // 灌进用户从没设过的键——所以两个候选名都要按「解释不了」处理。
  it("V0 文件是合法 JSON 但不是对象时两个候选都不认（数组/标量会读出一堆假键）", () => {
    writeLegacyFile("dsh-notifier.json", [1, 2]);
    writeLegacyFile("dsh-notifier.json.migrated.bak", '"这不是对象"');

    expect(readLegacySettings(makeSettings([]))).toEqual({});
  });

  it("两份来源都没有时给空对象（它就是「没有可迁的东西」的答案）", () => {
    expect(readLegacySettings(makeSettings([]))).toEqual({});
  });
});

describe("宿主文档文件：未注册命名空间的存量也读得到", () => {
  it("describe 里没有本插件命名空间（新架构不注册它）时，文档里的分节照样读出来", () => {
    const doc = writeDocument("dsh-notifier:\n  notifyTaskDone: false\n");
    // 这正是本块存在的理由：服务面只列已注册的命名空间，文档那条路必须自己把存量读出来。
    expect(readLegacySettings(makeSettings([], false, doc))).toEqual({ notifyTaskDone: false });
  });

  it("provider 没自报路径时按 DSH home 下的 settings.yaml 兜底", () => {
    // 路径由夹具自己拼（不走实现的任何 helper）：兜底名与兜底位置都得被独立钉住。
    writeDocument("dsh-notifier:\n  customKey: 42\n", "settings.yaml");
    expect(readLegacySettings(makeSettings([]))).toEqual({ customKey: 42 });
  });

  it("文档是 JSON 时同样能读（官方 provider 支持 .json 扩展名）", () => {
    writeDocument(`{"${NS}":{"notifyAsk":true}}`, "settings.json");
    expect(readLegacySettings(makeSettings([]))).toEqual({ notifyAsk: true });
  });

  it("`.json` 判定按扩展名而不是「碰巧 YAML 也读得动」", () => {
    // 重复键：YAML 解析器直接抛错，`JSON.parse` 取后者——只有真的走了 JSON 那条分支才读得出来。
    writeDocument(`{"${NS}":{"notifyAsk":true},"${NS}":{"notifyAsk":false}}`, "settings.json");
    expect(readLegacySettings(makeSettings([]))).toEqual({ notifyAsk: false });
  });

  it("provider 取文档路径就抛错时按没有文件处理（与服务面同形的失败处理）", () => {
    const settings: LegacySettingsFace = {
      describe: () =>
        [{ ns: NS, user: { notifyAsk: true } }] as unknown as ReturnType<
          LegacySettingsFace["describe"]
        >,
      get documentPath(): string | undefined {
        throw new Error("provider 取文档路径失败");
      },
    };
    expect(readLegacySettings(settings)).toEqual({ notifyAsk: true });
  });

  it("循环引用的分节按读不动处理（割接要把它序列化进 config.json）", () => {
    // YAML 别名可以自指：这样的分节落盘时会让 `JSON.stringify` 抛错，读的时候就得当它读不动、回退下一环。
    const doc = writeDocument("dsh-notifier: &self\n  notifyTaskDone: false\n  self: *self\n");
    expect(
      readLegacySettings(makeSettings([{ ns: NS, user: { notifyAsk: true } }], false, doc)),
    ).toEqual({ notifyAsk: true });
    expect(readLegacySettings(makeSettings([], false, doc))).toEqual({});
  });

  it("文档与服务面都有时以文档为准（它是用户提交的原始层，服务面给的是解析值）", () => {
    const doc = writeDocument("dsh-notifier:\n  notifyAsk: false\n");
    const settings = makeSettings([{ ns: NS, user: { notifyAsk: true } }], false, doc);
    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
  });

  it("文档解释不了时回退服务面，服务面也读不到时回退 V0（坏文件、缺分节、分节不是对象都不能把存量吃掉）", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: false });
    const broken = [
      "dsh-notifier:\n\tnotifyAsk: false\n",
      "other-plugin:\n  notifyAsk: false\n",
      'dsh-notifier: "不是对象"\n',
    ];
    for (const [index, text] of broken.entries()) {
      const doc = writeDocument(text, `broken-${index}.yaml`);
      expect(
        readLegacySettings(makeSettings([{ ns: NS, user: { notifyAsk: true } }], false, doc)),
      ).toEqual({ notifyAsk: true });
      // 服务面也给不出东西时，这一环同样不能把 V0 吃掉。
      expect(readLegacySettings(makeSettings([], false, doc))).toEqual({ notifyAsk: false });
    }
  });

  it("两个候选文件同时存在时 `.yaml` 优先（官方缺省名在前）", () => {
    writeDocument("dsh-notifier:\n  notifyAsk: false\n", "settings.yaml");
    writeDocument(`{"${NS}":{"notifyAsk":true}}`, "settings.json");
    expect(readLegacySettings(makeSettings([]))).toEqual({ notifyAsk: false });
  });

  it("documentPath 是空白串时按「没给出路径」处理，回到 DSH home 兜底", () => {
    writeDocument("dsh-notifier:\n  notifyAsk: false\n", "settings.yaml");
    for (const blank of ["", "   ", "\t"]) {
      expect(readLegacySettings(makeSettings([], false, blank))).toEqual({ notifyAsk: false });
    }
  });

  it("自报的路径指向不存在的文件时只回退服务面，不拿缺省名去猜（用户配过自定义路径）", () => {
    writeDocument("dsh-notifier:\n  notifyAsk: false\n", "settings.yaml");
    const missing = join(home.dir, "custom", "settings.yaml");
    expect(readLegacySettings(makeSettings([], false, missing))).toEqual({});
    expect(
      readLegacySettings(makeSettings([{ ns: NS, user: { notifyAsk: true } }], false, missing)),
    ).toEqual({ notifyAsk: true });
  });

  it("`.yml` 扩展名的文档按 YAML 解析（provider 支持它，只是缺省名是 yaml）", () => {
    const doc = writeDocument("dsh-notifier:\n  notifyAsk: false\n", "settings.yml");
    expect(readLegacySettings(makeSettings([], false, doc))).toEqual({ notifyAsk: false });
  });

  it("原型链上的危险键名不搬运（与 config 域写面同一份口径）", () => {
    const doc = writeDocument(
      `{"${NS}":{"notifyAsk":true,"__proto__":{"polluted":true},"constructor":"x","prototype":"y"}}`,
      "settings.json",
    );
    const out = readLegacySettings(makeSettings([], false, doc));
    expect(out).toEqual({ notifyAsk: true });
    expect(Object.getPrototypeOf(out)).toBe(Object.prototype);
  });

  it("文档来源同样做语义转换：装配键剔除、旧全局音效键摊到两个出口", () => {
    const doc = writeDocument(
      "dsh-notifier:\n  enabled: true\n  configFile: /legacy/config.json\n  notifySound: false\n  notifyTaskDone: false\n",
    );
    expect(readLegacySettings(makeSettings([], false, doc))).toEqual({
      notifySound: false,
      notifyTaskDone: false,
      browserSound: false,
      systemSound: false,
    });
  });
});

describe("语义转换：旧键 → 当前键", () => {
  it("剔掉装配键（新架构下它们是启动参数，留在配置里会被读成用户显式设置过的值）", () => {
    const legacy = readLegacySettings(
      makeSettings([
        {
          ns: NS,
          user: {
            enabled: true,
            configFile: "/tmp/config.json",
            historyFile: "/tmp/history.jsonl",
            statusFile: "/tmp/status.json",
            toastScript: "/tmp/toast.ps1",
            notifyAsk: false,
          },
        },
      ]),
    );
    expect(Object.keys(legacy)).toEqual(["notifyAsk"]);
    expect(legacy.notifyAsk).toBe(false);
  });

  it("旧的全局声音开关摊到两个出口键上（用户原来的选择不作废）", () => {
    const legacy = readLegacySettings(makeSettings([{ ns: NS, user: { notifySound: false } }]));
    expect(legacy.browserSound).toBe(false);
    expect(legacy.systemSound).toBe(false);
  });

  it("出口键已有值时不被旧键覆盖（新架构下用户已经分别选过）", () => {
    const legacy = readLegacySettings(
      makeSettings([{ ns: NS, user: { notifySound: true, browserSound: false } }]),
    );
    expect(legacy.browserSound).toBe(false);
    expect(legacy.systemSound).toBe(true);
  });

  it("契约不认识的键原样保留（可能是用户手写的或更高版本留下的，迁移没资格替他们决定丢哪些）", () => {
    const legacy = readLegacySettings(
      makeSettings([{ ns: NS, user: { customKey: 42, notifyAsk: true } }]),
    );
    expect(legacy.customKey).toBe(42);
    expect(legacy.notifyAsk).toBe(true);
  });
});

packages/dsh-notifier/test/unit/channels.source:
/**
 * dsh-notifier channels 域 bark 出口 —— 请求构造与失败分类。
 *
 * 判据为什么是这些：
 *  - `device_key` 是凭据，只许进 JSON body（反代访问日志默认记 URL 与 header）；
 *  - level 决定 iOS 上的紧急度：把 error 通知判成被动提示，用户在最需要的时候看不到它；
 *  - `retryable` 是**出口对失败的分类**（次数与退避归管线）：把 4xx 判成可重试会把用户的错误
 *    配置重投三次，把网络失败判成不可重试则静默丢通知。
 * 无网络：fetch 整体换成桩，`afterEach` 还原。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { sendBark } from "../../../src/server/channels/impl/bark/index.ts";
import type { BarkPushBody, BarkTarget } from "../../../src/server/channels/impl/bark/type.ts";
import type {
  NotifyMessage,
  NotifySeverity,
} from "../../../src/server/channels/impl/deliver/type.ts";
import { pollUntil, reasonOf, retryableOf, stubFetch, wire } from "../../helpers.ts";
import type { FetchCall } from "../../helpers.ts";

/** 2xx JSON 响应。 */
function jsonResponse(payload: unknown, status = 200): Response {
  return new Response(JSON.stringify(payload), { status });
}

/** 桩里记下的请求体（bark 要发的就是 `BarkPushBody`）。 */
function bodyOf(call: FetchCall): BarkPushBody {
  return JSON.parse(call.body) as BarkPushBody;
}

function targetOf(over: Partial<BarkTarget> = {}): BarkTarget {
  return {
    type: "bark",
    baseUrl: "http://127.0.0.1:40281/bark",
    deviceKey: "dk-secret-1",
    ...over,
  };
}

function messageOf(over: Partial<NotifyMessage> = {}): NotifyMessage {
  return { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("请求构造", () => {
  // 凭据进 URL 会留在反代访问日志里，那是密钥泄露最常见的一条路。
  it("device_key 只进 JSON body，URL 恰为 baseUrl + /push（凭据不进访问日志）", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));
    expect(await sendBark(targetOf(), messageOf())).toEqual({ status: "ok", stage: "delivered" });

    expect(calls).toHaveLength(1);
    const call = calls[0]!;
    expect(call.method).toBe("POST");
    expect(call.url).toBe("http://127.0.0.1:40281/bark/push");
    expect(call.headers["content-type"]).toBe("application/json; charset=utf-8");
    const body = bodyOf(call);
    expect(body.device_key).toBe("dk-secret-1");
    expect(body.title).toBe("标题");
    expect(body.body).toBe("正文");
  });

  // 错误通知被映射成被动提示等于在最需要的时候安静下来；非法值当合法用会发出对端不识别的 level。
  it("level 优先级：显式 level 覆盖 severity 映射；非法 severity 视同未提供", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));

    await sendBark(targetOf({ level: "critical" }), messageOf({ severity: "info" }));
    expect(bodyOf(calls[0]!).level).toBe("critical");

    // 失败通知必须穿透专注模式：映射到 passive 会让它在最需要的时候安静下来。
    await sendBark(targetOf(), messageOf({ severity: "failure" }));
    expect(bodyOf(calls[1]!).level).toBe("timeSensitive");

    await sendBark(targetOf(), messageOf({ severity: "info" }));
    expect(bodyOf(calls[2]!).level).toBe("passive");

    // `__proto__` 是唯一能区分布尔守卫「有没有做」的取值：它不在映射表里，但按原型链取得到
    // `Object.prototype`，没有 hasOwn 守卫时 level 会被写成 `{}`（`critical` 两边都是 undefined，恒绿）。
    await sendBark(targetOf(), messageOf({ severity: wire<NotifySeverity>("__proto__") }));
    expect("level" in bodyOf(calls[3]!)).toBe(false);
  });

  // 把没配置的字段发成空值会覆盖用户在 App 里的设置，而 badge 0 是有语义的「清角标」。
  it("可选字段有值才带：badge=0 是「清角标」而不是没配置", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));

    await sendBark(
      targetOf({ group: "组", sound: "bell", icon: "i", url: "https://example.com", badge: 0 }),
      messageOf(),
    );
    const full = bodyOf(calls[0]!);
    expect(full.group).toBe("组");
    expect(full.sound).toBe("bell");
    expect(full.icon).toBe("i");
    expect(full.url).toBe("https://example.com");
    expect(full.badge).toBe(0);

    await sendBark(targetOf(), messageOf());
    expect(Object.keys(bodyOf(calls[1]!)).sort()).toEqual(["body", "device_key", "title"]);
  });

  // 「只有 undefined 才省略」：空串是**有值**，要照发。这条区分了「没配置」与「配置成空」，
  // 而它此前只由实现本身承担（把判据改成 `sound !== ""` 时全套用例不红）。
  it("空串按「有值」写进 body：省略只针对 undefined", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));
    await sendBark(targetOf({ sound: "", group: "", url: "", icon: "" }), messageOf());
    const body = bodyOf(calls[0]!);
    expect(body.sound).toBe("");
    expect(body.group).toBe("");
    expect(body.url).toBe("");
    expect(body.icon).toBe("");
  });

  // 正文上限只在出口（定稿层只截标题），出口不截就会把超长正文整条发出去。
  it("出口自己也要截断：标题 64 / 正文 4096 码点（定稿层只截标题，正文上限只在出口）", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));
    await sendBark(targetOf(), messageOf({ title: "题".repeat(100), body: "文".repeat(5000) }));

    const body = bodyOf(calls[0]!);
    expect(Array.from(body.title)).toHaveLength(64);
    expect(Array.from(body.body)).toHaveLength(4096);
  });

  // 未知键是 README 承诺的前向兼容面（配置层已按 string/number 过滤）；已知键必须赢，
  // 否则配置里写一个 title 就能顶掉通知标题——那是透传面不该有的能力。
  it("实例的未知键原样进推送体，且已知键优先：透传不参与改写通知本身", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));
    await sendBark(
      targetOf({ extras: { volume: 5, call: "1", title: "顶掉标题", body: "顶掉正文" } }),
      messageOf({ title: "原标题", body: "原正文" }),
    );
    // 透传键不在 `BarkPushBody` 的声明里（它描述的是**已知**键的形状），故按开放视图看整份 body。
    const body = wire<Record<string, unknown>>(bodyOf(calls[0]!));
    expect(body.volume).toBe(5);
    expect(body.call).toBe("1");
    expect(body.title).toBe("原标题");
    expect(body.body).toBe("原正文");
  });

  // 调用方给的超时若不生效，一次挂死的推送会一直占着管线到出口的 10s 硬超时。
  it("timeoutMs 是真实的中止时限：到点即中止（不写就用出口自己的 10s 硬超时）", async () => {
    let aborted = false;
    stubFetch(
      (call) =>
        new Promise<Response>((_resolve, reject) => {
          call.signal?.addEventListener("abort", () => {
            aborted = true;
            reject(call.signal?.reason);
          });
        }),
    );

    const pending = sendBark(targetOf({ timeoutMs: 5 }), messageOf());
    await pollUntil(() => aborted, "5ms 超时应当中止请求", 2000);
    const result = await pending;
    expect(result.status).toBe("failed");
    expect(retryableOf(result)).toBe(true);
  });

  // 0 不是「立刻超时」而是「没配置」：把它当合法时限传下去，`AbortSignal.timeout(0)` 会在请求发出的
  // 同一刻中止——该频道从此每次都失败，而设置页上看不出任何异常。
  it("timeoutMs=0 视同未配置，回落出口自己的 10s 硬超时（0 不是「立刻超时」）", async () => {
    const calls = stubFetch(() => jsonResponse({ code: 200 }));
    // 钉「回落的是哪个数」，而不是「过了一小会儿还没中止」：`AbortSignal.timeout` 的 deadline 从外面
    // 读不出来，而真实 sleep 只能证明「还没触发」（实测：把硬超时常量错落成 100ms，25ms 的等待照样全绿；
    // 假时钟也管不到 `AbortSignal.timeout` 的原生计时器）。这里记账请求值，任何错落的时限都会现形。
    const requested: number[] = [];
    const realTimeout = AbortSignal.timeout.bind(AbortSignal);
    AbortSignal.timeout = (ms: number): AbortSignal => {
      requested.push(ms);
      return realTimeout(ms);
    };
    try {
      expect(await sendBark(targetOf({ timeoutMs: 0 }), messageOf())).toEqual({
        status: "ok",
        stage: "delivered",
      });
    } finally {
      AbortSignal.timeout = realTimeout;
    }
    expect(requested).toEqual([10_000]);
    expect(calls[0]!.signal?.aborted).toBe(false);
  });
});

describe("失败分类：只回答可不可重试，不自己重投", () => {
  // 反代用 200 包一张错误页时，只看 HTTP 状态会把「没送到」记成成功。
  it("成功判定双查 2xx 与响应体 code：反代用 200 包一张错误页时不算送到", async () => {
    const businessCode = stubFetch(() =>
      jsonResponse({ code: 400, message: "invalid device key" }),
    );
    const rejected = await sendBark(targetOf(), messageOf());
    expect(rejected).toMatchObject({ status: "failed", stage: "delivered", retryable: true });
    // 业务码与宿主原文分开断言：文案归客户端字典，服务端只负责这两段数据不串味。
    expect(reasonOf(rejected)).toEqual({
      code: "reasonBarkRejected",
      params: { code: "400" },
      detail: "invalid device key",
    });
    // 出口只投一次：重投决定权在管线（它看 retryable），出口自己不许偷偷重试。
    expect(businessCode).toHaveLength(1);

    const notJson = stubFetch(() => new Response("not json at all", { status: 200 }));
    expect(await sendBark(targetOf(), messageOf())).toEqual({ status: "ok", stage: "delivered" });
    expect(notJson).toHaveLength(1);
  });

  // 反代/中间件常回 2xx 包一个空对象：把「没有 code 键」判成失败，等于把一次成功投递记成故障
  // （而重试会把同一条通知再发两遍）。口径是「有 code 且 ≠200 才算失败」，不是「code 必须等于 200」。
  it("2xx 且响应体没有 code 键时按成功处理（只有 code 存在且非 200 才是失败）", async () => {
    const calls = stubFetch(() => jsonResponse({}));
    expect(await sendBark(targetOf(), messageOf())).toEqual({ status: "ok", stage: "delivered" });
    expect(calls).toHaveLength(1);
  });

  // 4xx 判可重试会把用户的错误配置重投三次，5xx 判不可重试则是静默丢通知。
  it("HTTP 状态分类：4xx 是确定失败，5xx 进可重试面；读不到响应体时原因只留状态码", async () => {
    const client = stubFetch(() => new Response("bad token", { status: 400 }));
    const rejected = await sendBark(targetOf(), messageOf());
    expect(retryableOf(rejected)).toBe(false);
    expect(reasonOf(rejected)).toEqual({
      code: "reasonBarkHttp",
      params: { status: 400 },
      detail: "bad token",
    });
    expect(client).toHaveLength(1);

    const server = stubFetch(() => new Response("boom", { status: 503 }));
    const serverError = await sendBark(targetOf(), messageOf());
    expect(retryableOf(serverError)).toBe(true);
    expect(reasonOf(serverError)).toEqual({
      code: "reasonBarkHttp",
      params: { status: 503 },
      detail: "boom",
    });
    expect(server).toHaveLength(1);

    // 边界取 500 本身：判据写成 `> 500` 会把恰好 500 的服务端故障当成终态，静默丢掉一次可恢复的失败。
    const exactly500 = stubFetch(() => new Response("boom", { status: 500 }));
    const serverFault = await sendBark(targetOf(), messageOf());
    expect(retryableOf(serverFault)).toBe(true);
    expect(reasonOf(serverFault)).toEqual({
      code: "reasonBarkHttp",
      params: { status: 500 },
      detail: "boom",
    });
    expect(exactly500).toHaveLength(1);

    stubFetch(
      () =>
        ({
          ok: false,
          status: 503,
          text: () => Promise.reject(new Error("响应体读取中断")),
        }) as unknown as Response,
    );
    // 读不到响应体时 detail 缺席（不是空串）：状态码本身已是完整原因
    expect(reasonOf(await sendBark(targetOf(), messageOf()))).toEqual({
      code: "reasonBarkHttp",
      params: { status: 503 },
    });
  });

  // 网络失败被判成终态就是静默丢通知；原因不封顶会把状态页撑爆。
  it("网络失败与响应体读取中断同属可重试面，原因按 300 码点封顶", async () => {
    stubFetch(() => {
      throw new Error("长".repeat(400));
    });
    const offline = await sendBark(targetOf(), messageOf());
    expect(offline.status).toBe("failed");
    expect(retryableOf(offline)).toBe(true);
    expect(reasonOf(offline)).toEqual({
      code: "reasonBarkRequestFailed",
      detail: "长".repeat(300),
    });
    expect(reasonOf(offline).detail).toHaveLength(300);

    stubFetch(
      () =>
        ({
          ok: true,
          status: 200,
          json: () => Promise.reject(new TypeError("terminated")),
        }) as unknown as Response,
    );
    const interrupted = await sendBark(targetOf(), messageOf());
    expect(interrupted.status).toBe("failed");
    expect(retryableOf(interrupted)).toBe(true);
    expect(reasonOf(interrupted)).toEqual({
      code: "reasonBarkBodyUnreadable",
      detail: "terminated",
    });
  });
});

/**
 * dsh-notifier channels 域 webhook 出口 —— 模板渲染与认证头。
 *
 * 判据为什么是这些：
 *  - 模板是用户自由文本，渲染是**注入面**：JSON-aware 两步法若退化成拼字符串，用户标题里的一个
 *    引号就能改掉整个请求体（发到用户自己配的端点上，等于把通知内容交给别人构造）；
 *  - 凭据只走请求头、且同名头只能有一份（两份 content-type 会被对端按未定义行为处理）；
 *  - 失败零重试是硬约束：webhook 不是幂等 POST，重投等于让对端把同一条通知处理两遍。
 * 无网络：fetch 整体换成桩，`afterEach` 还原。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  clampTimeoutSec,
  renderWebhookBody,
  priorityFor,
  sendWebhook,
} from "../../../src/server/channels/impl/webhook/index.ts";
import type {
  WebhookPreset,
  WebhookTarget,
} from "../../../src/server/channels/impl/webhook/type.ts";
import type {
  NotifyMessage,
  NotifySeverity,
} from "../../../src/server/channels/impl/deliver/type.ts";
import { reasonOf, retryableOf, stubFetch, wire } from "../../helpers.ts";

/** 渲染变量；`ts` 写死，免得断言跟着运行时刻漂。 */
function varsOf(over: Partial<Parameters<typeof renderWebhookBody>[2]> = {}) {
  return { title: "标题", message: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

function targetOf(over: Partial<WebhookTarget> = {}): WebhookTarget {
  return { type: "webhook", url: "http://127.0.0.1:40281/hook", preset: "raw", ...over };
}

function messageOf(over: Partial<NotifyMessage> = {}): NotifyMessage {
  return { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("模板渲染（纯函数，无网络）", () => {
  // 预设模板是对端 API 的契约：键名或结构漂移，用户的 ntfy/gotify 就再也收不到。
  it("空模板回落到预设默认模板，三个预设的顶层键各自固定", () => {
    const ntfy = JSON.parse(renderWebhookBody("", "ntfy", varsOf({ severity: "failure" })));
    expect(Object.keys(ntfy).sort()).toEqual(["message", "priority", "tags", "title", "topic"]);
    expect(ntfy.priority).toBe("urgent");

    const gotify = JSON.parse(renderWebhookBody("", "gotify", varsOf({ severity: "failure" })));
    expect(Object.keys(gotify).sort()).toEqual(["message", "priority", "title"]);
    expect(gotify.priority).toBe("9");

    const raw = JSON.parse(renderWebhookBody("", "raw", varsOf({ severity: "failure" })));
    expect(Object.keys(raw).sort()).toEqual(["body", "event", "severity", "title", "ts"]);
    expect(raw.event).toBe("done");
    expect(raw.body).toBe("正文");
    // raw 的 {{severity}} 是强度原文：回落成空串等于对端永远看不到这次通知的严重性。
    expect(raw.severity).toBe("failure");
  });

  // {{ts}} 若进了字符串占位符白名单，raw 模板的裸数字会变成字符串，对端解析直接报错。
  it("{{ts}} 只在文本层做裸值替换（数字直出，进 JSON 后才成立）并按毫秒取整", () => {
    const parsed = JSON.parse(
      renderWebhookBody('{"ts": {{ts}}}', "raw", varsOf({ ts: 1_700_000_000_000.6 })),
    );
    expect(parsed.ts).toBe(1_700_000_000_001);
    expect(typeof parsed.ts).toBe("number");
  });

  // 标题里的引号若能闭合 JSON 字符串，用户的通知内容就能改写整个请求体。
  it("文本占位符替换后重新序列化：引号与换行逃不出字符串（JSON 注入面）", () => {
    const title = 'a"b\\c\nd';
    const message = '}},"evil":true,"z":"';
    const parsed = JSON.parse(
      renderWebhookBody(
        '{"title":"{{title}}","message":"{{message}}"}',
        "raw",
        varsOf({ title, message }),
      ),
    );
    expect(parsed.title).toBe(title);
    expect(parsed.message).toBe(message);
    expect(parsed.evil).toBeUndefined();
  });

  // 二次扫描会让「正文里写占位符」变成一只自我复制的注入源。
  it("替换内容不被二次扫描：正文里写 {{title}} 会原样留下", () => {
    const parsed = JSON.parse(
      renderWebhookBody(
        '{"title":"{{title}}","message":"{{message}}"}',
        "raw",
        varsOf({ title: "A", message: "{{title}}" }),
      ),
    );
    expect(parsed.message).toBe("{{title}}");
    expect(parsed.title).toBe("A");
  });

  // 把不认识的占位符清空，会静默删掉用户自己写的字面量。
  it("占位符白名单：容许两侧空白，不认识的原样保留（不猜也不清空用户自己写的字面量）", () => {
    const parsed = JSON.parse(
      renderWebhookBody('{"k":"{{ kind }}","topic":"{{topic}}"}', "raw", varsOf({ kind: "error" })),
    );
    expect(parsed.k).toBe("error");
    expect(parsed.topic).toBe("{{topic}}");
  });

  // 降级成文本发送会让对端收到解析不了的 body，而历史里看起来是「已送达」。
  it("非法 JSON 模板抛错：宁可这次投递失败，也不降级成文本发送", () => {
    expect(() => renderWebhookBody("{", "raw", varsOf())).toThrow(/不是合法 JSON/u);
  });

  // 缺省回落若产出字面量 undefined，对端会收到一个非法优先级。
  it("priority 值表与缺省回落：没有 severity 时不得产出字面量 undefined", () => {
    const table: ReadonlyArray<readonly [WebhookPreset, NotifySeverity | undefined, string]> = [
      ["ntfy", "failure", "urgent"],
      ["ntfy", "info", "default"],
      ["ntfy", undefined, "default"],
      ["gotify", "failure", "9"],
      ["gotify", undefined, "3"],
      ["raw", "failure", "failure"],
      ["raw", undefined, ""],
    ];
    for (const [preset, severity, expected] of table) {
      expect(priorityFor(preset, severity), `${preset}/${String(severity)}`).toBe(expected);
    }
    // `__proto__` 是唯一能区分布尔守卫「有没有做」的取值：它不在映射表里，但按原型链取得到
    // `Object.prototype`，没有 hasOwn 守卫时回落分支根本不执行（`critical` 两边都是 undefined，恒绿）。
    expect(priorityFor("ntfy", wire<NotifySeverity>("__proto__"))).toBe("default");
    expect(priorityFor("raw", wire<NotifySeverity>("__proto__"))).toBe("");
  });
});

describe("投递：凭据只走请求头，失败即终态", () => {
  // 两份同名头是对端的未定义行为；凭据进 URL 或 body 则会留在日志与请求记录里。
  it("bearer / basic 各就其位，凭据不进 URL 与 body，同名自定义头不产生第二份 content-type", async () => {
    const calls = stubFetch(() => new Response("{}", { status: 200 }));

    await sendWebhook(
      targetOf({
        headers: { "Content-Type": "text/plain", "x-custom": "1" },
        auth: { kind: "bearer", token: "tk-1" },
      }),
      messageOf(),
    );
    const headers = calls[0]!.headers;
    expect(headers["authorization"]).toBe("Bearer tk-1");
    expect(headers["x-custom"]).toBe("1");
    expect(headers["content-type"]).toBe("application/json; charset=utf-8");
    expect(Object.keys(headers).filter((key) => key.toLowerCase() === "content-type")).toEqual([
      "content-type",
    ]);
    expect(calls[0]!.url).not.toContain("tk-1");
    expect(calls[0]!.body).not.toContain("tk-1");

    await sendWebhook(
      targetOf({ auth: { kind: "basic", user: "user", password: "pass" } }),
      messageOf(),
    );
    expect(calls[1]!.headers["authorization"]).toBe("Basic dXNlcjpwYXNz");
    expect(calls[1]!.body).not.toContain("pass");
  });

  // 跨边界喂入未知认证形状：类型围栏只在编译期，运行时仍可能到；凭据一旦拼进 URL 就会留在
  // 对端访问日志、代理与浏览器历史里（请求头不会）。
  it("未知认证形状：凭据不进 URL 与查询串，请求仍照发（已删掉的 query 成员不得复活）", async () => {
    const calls = stubFetch(() => new Response("{}", { status: 200 }));
    const secret = "query-secret-9f2a";
    const result = await sendWebhook(
      targetOf({
        auth: wire<NonNullable<WebhookTarget["auth"]>>({
          kind: "query",
          name: "token",
          value: secret,
        }),
      }),
      messageOf(),
    );

    expect(result.status).toBe("ok");
    expect(calls).toHaveLength(1);
    // 判的是实际发出的 URL，而不是「没抛错」：拼进查询串的凭据在 URL 上，等于写进对端日志。
    expect(calls[0]!.url).not.toContain(secret);
    expect(calls[0]!.url).not.toContain("token");
    expect(new URL(calls[0]!.url).search).toBe("");
    expect(calls[0]!.headers["authorization"]).toBeUndefined();
    expect(calls[0]!.body).not.toContain(secret);
  });

  // 抛穿会把一次投递失败升级成批次失败，还可能让调用方重试整批。
  it("模板渲染失败落成这次投递的失败且不发请求（retryable=false）：坏 body 不如不发", async () => {
    const calls = stubFetch(() => new Response("{}", { status: 200 }));
    const result = await sendWebhook(targetOf({ template: "{" }), messageOf());
    expect(result.status).toBe("failed");
    expect(retryableOf(result)).toBe(false);
    const reason = reasonOf(result);
    expect(reason.code).toBe("reasonWebhookTemplateInvalid");
    // 宿主原文（JSON.parse 的报错）不作主文案，但必须留下来供定位
    expect(reason.detail).toContain("webhook 模板不是合法 JSON");
    expect(calls).toHaveLength(0);
  });

  // webhook 不幂等：重投等于让对端把同一条通知处理两遍。
  it("HTTP 非 2xx 与网络错误都标不可重试（webhook 不幂等，重投等于让对端处理两遍）", async () => {
    stubFetch(() => new Response("nope", { status: 401 }));
    const unauthorized = await sendWebhook(targetOf(), messageOf());
    expect(unauthorized).toMatchObject({ status: "failed", stage: "delivered", retryable: false });
    expect(reasonOf(unauthorized)).toEqual({
      code: "reasonWebhookHttp",
      params: { status: 401 },
      detail: "nope",
    });

    stubFetch(() => {
      throw new Error("ECONNREFUSED");
    });
    const offline = await sendWebhook(targetOf(), messageOf());
    expect(retryableOf(offline)).toBe(false);
    expect(reasonOf(offline)).toEqual({
      code: "reasonWebhookRequestFailed",
      detail: "ECONNREFUSED",
    });
  });

  // AbortSignal.timeout 只接受有限非负数：NaN 与负数都当场抛 RangeError，异常冒到 fetch 的
  // catch 里就变成「每一次投递都失败」——clamp 正是拦在它前面。用例因此判的是「有 clamp 才发得出去」。
  it("timeoutSec 脏值被夹进 1..60 秒：负数与 NaN 都不再让 AbortSignal.timeout 抛 RangeError", async () => {
    const calls = stubFetch(() => new Response("{}", { status: 200 }));

    expect((await sendWebhook(targetOf({ timeoutSec: -5 }), messageOf())).status).toBe("ok");
    expect(calls[0]!.signal?.aborted).toBe(false);

    expect((await sendWebhook(targetOf({ timeoutSec: Number.NaN }), messageOf())).status).toBe(
      "ok",
    );
    expect(calls[1]!.signal?.aborted).toBe(false);
  });

  // 上界与下界是**唯一**箍：配置层允许到 600，而 clamp 的产物只落在 AbortSignal 的 deadline 上，
  // 从外面读不出来（改宽上界、把下界改成 0 都不影响「请求发出去了」）。故这里直接判函数值。
  it.each<[string, number | undefined, number]>([
    ["负数 → 下界", -5, 1],
    ["0 → 下界", 0, 1],
    ["下界本身保留", 1, 1],
    ["上界本身保留", 60, 60],
    ["配置层允许的 600 也被收到上界", 600, 60],
    ["NaN → 缺省", Number.NaN, 10],
    ["undefined（未配置）→ 缺省", undefined, 10],
  ])("timeoutSec clamp（%s）：%s → %s 秒", (_label, value, expected) => {
    expect(clampTimeoutSec(value)).toBe(expected);
  });

  // 状态页只显示一行，未截断的长原因会把它撑坏并挤掉别的信息。
  it("失败原因按 300 码点封顶（状态页只显示一行，原因是摘要不是全文）", async () => {
    stubFetch(() => {
      throw new Error("长".repeat(400));
    });
    const result = await sendWebhook(targetOf(), messageOf());
    expect(reasonOf(result).code).toBe("reasonWebhookRequestFailed");
    expect(Array.from(reasonOf(result).detail ?? "")).toHaveLength(300);
  });
});

packages/dsh-notifier/test/unit/api/serv.source:
/**
 * dsh-notifier api 域 service 块 —— 装配面：路径表（对客户端的完整承诺）、接线、生命周期。
 *
 * 这一层只有装配面看得见的东西才值得测：哪 8 条路径被挂上、每条路径认哪些方法、四个端点各拿到
 * 的是哪份能力面（把 stores 接到设置端点是编译期拦不住的错位）、卸载时路由与帧订阅是否真的收回。
 * 单条端点的判据在各自的块里测，这里不重复。
 *
 * 隔离纪律：序号文件的路径在**模块加载期**就被 `streamHub` 定下（`notifierFile()` 在类字段
 * 初始化里跑，见 `impl/stream`）。故临时 `DSH_HOME` 必须先于 api 模块的导入建立——用顶层 await
 * 动态导入而不是静态导入，否则 `installApi` 会去读真实 `~/.dsh` 下的 `seq.json`。
 */
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { IncomingMessage, ServerResponse } from "node:http";
import { afterAll, afterEach, describe, expect, it } from "vitest";

import type { ApiDeps, HostCapabilities, OutgoingFrame } from "../../../src/server/api/deps.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import { jsonReq, makeLogger, makeRegister, pollUntil, tempDshHome, wire } from "../../helpers.ts";

const home = tempDshHome();
const { installApi, releaseApi } = await import("../../../src/server/api/interface.ts");

/**
 * 客户端锁定的路径表（`src/client/index.tsx` 里的 URL 常量是同一份承诺）。独立写一遍而不是从源码
 * 导：改路径就要两端同改，两边都从同一个常量取的话，改一处会让两边一起变绿。
 */
const PATHS = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
] as const;

/** 能力面夹具：本文件只验「两个自检端点拿到的是 channels 域给的那一份」，形状细节归 api/probe 的用例。 */
const CAPABILITIES: HostCapabilities = {
  verdict: "degraded",
  unknownDimensions: [],
  popup: { state: "ok", checked: ["notify-send", "dbus-name-owner", "session-bus"] },
  sound: {
    state: "degraded",
    players: ["pw-play"],
    toneFileAvailable: false,
    checked: ["players", "tone-file"],
  },
  remediation: [{ code: "host-no-tone-file" }],
};

/** 路径 → 它认的方法。`allow` 头会把这行字逐条回给客户端，故它同时是 405 判据的期望值。 */
const METHOD_TABLE: ReadonlyArray<readonly [string, readonly string[]]> = [
  ["/api/dsh-notifier/config", ["GET", "PUT"]],
  ["/api/dsh-notifier/history", ["GET", "DELETE"]],
  ["/api/dsh-notifier/status", ["GET"]],
  ["/api/dsh-notifier/kinds", ["GET", "POST"]],
  ["/api/dsh-notifier/test", ["POST"]],
  ["/api/dsh-notifier/health", ["GET"]],
  ["/api/dsh-notifier/diagnostics", ["GET"]],
  ["/api/dsh-notifier/events", ["GET"]],
];

afterEach(() => {
  releaseApi();
});

afterAll(() => {
  home.dispose();
});

/** 假请求：合法回环，body 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(options: { method?: string; url: string; body?: unknown }): IncomingMessage {
  return jsonReq({ method: options.method ?? "GET", url: options.url, body: options.body });
}

/** 假响应：JSON 端点与 SSE 端点共用（SSE 需要 `on`/`destroy` 才能被连接表收下）。 */
function makeRes() {
  const rec = {
    status: 0,
    headers: {} as Record<string, string>,
    text: "",
    headersSent: false,
    destroyed: false,
  };
  const listeners = new Map<string, Array<() => void>>();
  const res = {
    get headersSent() {
      return rec.headersSent;
    },
    get destroyed() {
      return rec.destroyed;
    },
    get writableEnded() {
      return false;
    },
    writeHead(status: number, headers?: Record<string, string>) {
      rec.status = status;
      rec.headers = { ...(headers ?? {}) };
      rec.headersSent = true;
      return res;
    },
    write(chunk: string) {
      rec.text += chunk;
      return true;
    },
    end(chunk?: string) {
      if (chunk !== undefined) rec.text += chunk;
      rec.headersSent = true;
      return res;
    },
    on(event: string, handler: () => void) {
      listeners.set(event, [...(listeners.get(event) ?? []), handler]);
      return res;
    },
    destroy() {
      rec.destroyed = true;
      for (const handler of listeners.get("close") ?? []) handler();
    },
  };
  return {
    res: res as unknown as ServerResponse,
    rec,
    json: (): Record<string, unknown> => JSON.parse(rec.text),
  };
}

/** 假帧入口：handler 捕获下来手动触发，退订记账。 */
function makeFrameInlet() {
  const handlers: Array<(payload: OutgoingFrame) => void> = [];
  let disposed = 0;
  return {
    handlers,
    disposedCount: () => disposed,
    port: {
      onFrame: (handler: (payload: OutgoingFrame) => void) => {
        handlers.push(handler);
        return () => {
          disposed += 1;
        };
      },
    },
  };
}

/** 各能力面返回带标记的值：端点回给我的标记来自哪一份面，一读就知道有没有接错线。 */
const HISTORY = [{ ts: 1, kind: "done", title: "历史", message: "正文" }];
const STATUS = { "bark:main": { lastTs: 1, lastStatus: "ok" as const, failStreak: 0 } };
const KINDS = [{ id: "demo:x", label: "X", confirmed: false }];

/** 装配一次 api 域，交出全部观测面。 */
function assemble() {
  const hub = makeRegister();
  const frames = makeFrameInlet();
  const logger = makeLogger();
  const submitted: Array<{ kind: string }> = [];
  const deps: ApiDeps = {
    register: hub.register,
    frames: frames.port,
    logger,
    config: {
      readConfig: () => ({ ...DEFAULT_CONFIG, maxConnections: 4 }),
      readSettingsView: () => ({
        user: { notifyAsk: false },
        revision: 7,
        writable: true,
        effective: { notifyAsk: false },
      }),
      writeConfig: async () => ({
        ok: true,
        view: { user: {}, revision: 8, writable: true, effective: {} },
      }),
    },
    stores: {
      readHistory: async () => [...HISTORY],
      clearHistory: async () => 2,
      readStatus: async () => ({ ...STATUS }),
    },
    pipeline: {
      submit: (request) => {
        submitted.push(request);
      },
    },
    kinds: {
      listKinds: () => [...KINDS],
      confirmKind: async () => ({
        ok: true,
        view: { user: {}, revision: 9, writable: true, effective: {} },
      }),
    },
    channels: {
      probeCapabilities: () => Promise.resolve(CAPABILITIES),
      hostPlatform: () => "linux",
      undeterminedCapabilities: () => CAPABILITIES,
    },
  };
  installApi(deps);
  return { hub, frames, logger, submitted };
}

/** 取一条已注册的路由；没注册就直接抛，免得后面的断言在 undefined 上假绿。 */
function routeOf(routes: WebRoute[], path: string): WebRoute {
  const route = routes.find((item) => item.path === path);
  if (route === undefined) throw new Error(`路由未注册: ${path}`);
  return route;
}

/**
 * 走一次真实路由并等响应落地。壳对异步端点的 promise 只做 `catch` 收口、不往上传（见 route 块），
 * 故 `handler()` 立刻返回 undefined——等响应只能靠轮询 `headersSent`。
 */
async function request(routes: WebRoute[], path: string, req: IncomingMessage) {
  const captured = makeRes();
  routeOf(routes, path).handler(req, captured.res);
  await pollUntil(() => captured.rec.headersSent, `${path} 未写出响应`);
  return captured;
}

describe("路径表：对客户端的完整承诺", () => {
  it("恰好 8 条路径，且全部按 exact 注册（多一条就是多开一个浏览器入口）", () => {
    const { hub } = assemble();
    expect([...hub.routes.map((route) => route.path)].sort()).toEqual([...PATHS].sort());
    expect([...new Set(hub.routes.map((route) => route.kind))]).toEqual(["exact"]);
  });

  it.each(METHOD_TABLE)("%s 的方法表由 405 的 allow 头逐条列出", async (path, methods) => {
    const { hub } = assemble();
    const { rec, json } = await request(hub.routes, path, makeReq({ method: "PATCH", url: path }));
    expect(rec.status).toBe(405);
    expect(rec.headers.allow).toBe(methods.join(", "));
    expect(json()).toEqual({ error: "method not allowed: PATCH" });
  });
});

describe("接线：端点与能力面一一对应", () => {
  it("四个端点各拿到自己那份能力面（接错线在编译期是合法的，只有装配面看得见）", async () => {
    const { hub, submitted } = assemble();

    const config = await request(
      hub.routes,
      "/api/dsh-notifier/config",
      makeReq({ url: "/api/dsh-notifier/config" }),
    );
    expect(config.json().revision).toBe(7);

    const history = await request(
      hub.routes,
      "/api/dsh-notifier/history",
      makeReq({ url: "/api/dsh-notifier/history" }),
    );
    expect(history.json().records).toEqual(HISTORY);

    const kinds = await request(
      hub.routes,
      "/api/dsh-notifier/kinds",
      makeReq({ url: "/api/dsh-notifier/kinds" }),
    );
    expect(kinds.json().kinds).toEqual(KINDS);

    const test = await request(
      hub.routes,
      "/api/dsh-notifier/test",
      makeReq({ method: "POST", url: "/api/dsh-notifier/test" }),
    );
    expect(test.rec.status).toBe(200);
    expect(submitted.map((entry) => entry.kind)).toEqual(["test"]);

    // 两个自检端点都要拿到 channels 域那一份：接错线（少传 `channels`）在编译期是合法的。
    const health = await request(
      hub.routes,
      "/api/dsh-notifier/health",
      makeReq({ url: "/api/dsh-notifier/health" }),
    );
    const healthHost = wire<{ capabilities: { host: { verdict: string } } }>(health.json());
    expect(healthHost.capabilities.host.verdict).toBe("degraded");

    const diagnostics = await request(
      hub.routes,
      "/api/dsh-notifier/diagnostics",
      makeReq({ url: "/api/dsh-notifier/diagnostics" }),
    );
    const diagnosticsHost = wire<{ capabilities: { host: HostCapabilities } }>(diagnostics.json());
    // 摘要与完整面必须同源：`/diagnostics` 给的就是装配接上的那一份（含 checked 与 remediation）。
    expect(diagnosticsHost.capabilities.host).toEqual(CAPABILITIES);
  });

  it("装配同时接上帧入口：帧经 /events 回放给新连接（接线断了页面永远收不到通知）", async () => {
    const { hub, frames } = assemble();
    expect(frames.handlers).toHaveLength(1);
    frames.handlers[0]!({
      kind: "done",
      frame: {
        pop: true,
        sound: { mode: "system" },
        whenVisible: false,
        title: "标题",
        body: "正文",
      },
    });

    const { rec } = await request(
      hub.routes,
      "/api/dsh-notifier/events",
      makeReq({ url: "/api/dsh-notifier/events" }),
    );
    expect(rec.headers["content-type"]).toBe("text/event-stream; charset=utf-8");
    expect(rec.text).toContain("标题");
  });
});

describe("生命周期", () => {
  it("release 摘掉全部路由与帧订阅（卸载后路由还在，等于插件卸载没生效）", () => {
    const { hub, frames } = assemble();
    expect(hub.disposed).toEqual([]);

    releaseApi();

    expect([...hub.disposed].sort()).toEqual([...PATHS].sort());
    expect(frames.disposedCount()).toBe(1);
  });

  it("重复装配当场抛错，release 之后可以再装配（卸载链可能走到不止一次）", () => {
    assemble();
    expect(() => assemble()).toThrow(/只能装配一次/u);
    releaseApi();
    releaseApi();
    // 只断「没抛」不够：装上了与**静默空转**都不抛（实测把 install 改成见标记即 return，这条照样绿）。
    // 再装配的实质是「8 条路由又被挂回去」，就判这个。
    const again = assemble();
    expect(again.hub.routes.map((route) => route.path).sort()).toEqual([...PATHS].sort());
  });
});

packages/dsh-notifier/test/integration/s.source:
/**
 * dsh-notifier — 对外服务面契约（`wingsky.notifier`）。
 *
 * 面口径：这是**兄弟插件看到的那一面**。经 `sdk/interface.ts` 装配（与组合根同一条路径），
 * 只伪 `sdk/deps.ts` 声明的那三个端口；域内管理面（清单 / 确认）也在这里测，因为它回答的是
 * 「用户答不答应」，只有设置页该问——挂在服务面上等于任何插件都能替用户点头。
 *
 * 装配纪律：`sdkService` 与 `kindRegistry` 都是模块级单例（源码注释明写「类不外放，外面 new 不出
 * 第二份」），故每个用例后必须 `releaseSdk()`，否则下一个 `installSdk` 当场抛「只能装配一次」；
 * 注册表没有重置口，故用例之间用互不相同的 id，断言一律用 `toContainEqual` 而不是整体相等。
 */
import { afterEach, describe, expect, it } from "vitest";

import { DEFAULT_CONFIG } from "../../src/server/config/impl/model/index.ts";
import { isBuiltinKind } from "../../src/server/pipeline/interface.ts";
import type { ConfigPort, ExposePort, PipelinePort, SdkDeps } from "../../src/server/sdk/deps.ts";
import {
  NOTIFIER_SERVICE,
  confirmKind,
  installSdk,
  listKinds,
  releaseSdk,
} from "../../src/server/sdk/interface.ts";
import type { NotifierService } from "../../src/server/sdk/interface.ts";

/** 服务面入参：经签名可达，不必请 impl 再导出一个名字。 */
type SendInput = Parameters<NotifierService["send"]>[0];
type RegisterInput = Parameters<NotifierService["registerKind"]>[0];

/**
 * 绕过类型造一个「未走类型的调用方」（JS 插件）才会送出的形状。
 * 守卫用例只能这样写：这些形状在编译期本就被拦住，而守卫存在的理由正是编译期管不到的那一侧。
 */
function untyped<T>(value: Record<string, unknown>): T {
  return value as unknown as T;
}

/**
 * config 端口：读面给可变设置的快照，写面记账并让 `allowKinds` 生效（确认是读改写，撤销要靠它才成立）。
 * 配置对象取自 `config/impl/model` 的默认值表：它是值表而不是 config 域的服务，且经
 * `config/interface.ts` 取不到（那里只出类型）——手抄二十个字段等于把默认值抄成第二份事实源。
 */
function fakeConfig(allowKinds: readonly string[] = []) {
  const writes: Array<Parameters<ConfigPort["writeConfig"]>[0]> = [];
  const state = { allowKinds: [...allowKinds] };
  const port: ConfigPort = {
    readConfig: () => ({ ...DEFAULT_CONFIG, allowKinds: [...state.allowKinds] }),
    writeConfig: async (patch) => {
      writes.push(patch);
      const next = patch.allowKinds;
      if (Array.isArray(next)) state.allowKinds = next.map((value) => String(value));
      return { ok: true, view: { user: {}, revision: 1, writable: true, effective: {} } };
    },
  };
  return { port, writes };
}

/**
 * pipeline 端口：提交口记账，`isBuiltinKind` 用生产实现——它是纯函数而不是被测对象，且
 * 「内置名单只有一份」正是本域不抄它的理由（抄一份，新增内置种类时两边会给出不同答案）。
 */
function fakePipeline() {
  const submitted: Array<Parameters<PipelinePort["submit"]>[0]> = [];
  const port: PipelinePort = {
    isBuiltinKind,
    submit: (request) => {
      submitted.push(request);
    },
  };
  return { port, submitted };
}

/** 宿主出口：记下交出来的服务对象与摘除次数。 */
function fakeExpose() {
  const provided: NotifierService[] = [];
  let disposed = 0;
  const port: ExposePort = {
    provide: (service) => {
      provided.push(service);
      return () => {
        disposed += 1;
      };
    },
  };
  return { port, provided, disposedCount: () => disposed };
}

/** 装配一次，交出四件观测物。 */
function assemble(allowKinds: readonly string[] = []) {
  const config = fakeConfig(allowKinds);
  const pipeline = fakePipeline();
  const expose = fakeExpose();
  const deps: SdkDeps = { expose: expose.port, config: config.port, pipeline: pipeline.port };
  installSdk(deps);
  return { service: expose.provided[0], config, pipeline, expose };
}

afterEach(() => {
  releaseSdk();
});

describe("装配面", () => {
  it("装配后交出服务面：apiVersion 为 2，且不夹带确认与清单（授权边界靠运行时形状守）", () => {
    const { service, expose } = assemble();
    expect(NOTIFIER_SERVICE).toBe("wingsky.notifier");
    expect(service.apiVersion).toBe(2);
    expect(expose.provided).toHaveLength(1);
    // 两个口的存在性由 `implements NotifierService` 在编译期保证，这里只守「不多给」：
    // 多一个成员就是把本域的内部状态变成公共 API，而公共 API 从此不能再改。
    expect("confirmKind" in service).toBe(false);
    expect("listKinds" in service).toBe(false);
  });

  it("重复装配当场抛错（单例语义：装配守卫不留半装配状态）", () => {
    assemble();
    expect(() => assemble()).toThrow(/只能装配一次/u);
  });

  it("release 收回服务面：摘除器被调用，此后管理面报「未装配」而不是静默空值", async () => {
    const { service, expose } = assemble();
    service.registerKind({ id: "svc-release:a", label: "A" });
    releaseSdk();
    expect(expose.disposedCount()).toBe(1);
    expect(() => listKinds()).toThrow(/尚未装配/u);
    await expect(confirmKind("svc-release:a", true)).rejects.toThrow(/尚未装配/u);
  });
});

describe("send：本域只做形状收窄，不判该不该发", () => {
  it("内置种类直通管线；缺省标题补中性文案（空标题在系统通知里看起来像一条残缺记录）", async () => {
    const { service, pipeline } = assemble();
    await service.send({ kind: "done", body: "正文" });
    expect(pipeline.submitted).toEqual([{ kind: "done", title: "DSH 通知", body: "正文" }]);
    expect("severity" in pipeline.submitted[0]!).toBe(false);
  });

  it("自填标题与 severity 原样进管线", async () => {
    const { service, pipeline } = assemble();
    await service.send({ kind: "demo:report", title: "自定义", body: "正文", severity: "warning" });
    expect(pipeline.submitted).toEqual([
      { kind: "demo:report", title: "自定义", body: "正文", severity: "warning" },
    ]);
  });

  // 空串标题与「没给标题」对用户是同一件事：空标题在系统通知里看起来像一条残缺记录。
  // 只测缺席那一档的话，把判据退化成「有字符串就用」也全绿。
  it("标题是空串时同样补中性文案（判的是非空，不是「有没有给字符串」）", async () => {
    const { service, pipeline } = assemble();
    await service.send({ kind: "done", title: "", body: "正文" });
    expect(pipeline.submitted).toEqual([{ kind: "done", title: "DSH 通知", body: "正文" }]);
  });

  it("形状守卫：非法种类与非字符串正文一律 reject（调用方应在调用点 catch）", async () => {
    const { service, pipeline } = assemble();
    await expect(
      service.send(untyped<SendInput>({ kind: "no-colon", body: "正文" })),
    ).rejects.toThrow(/种类非法/u);
    // 命名空间撞内置名：`ask:foo` 查不到任何事件开关，放行它等于放行一条无归属的通知。
    await expect(
      service.send(untyped<SendInput>({ kind: "ask:foo", body: "正文" })),
    ).rejects.toThrow(/种类非法/u);
    await expect(service.send(untyped<SendInput>({ kind: "done", body: 42 }))).rejects.toThrow(
      /正文/u,
    );
    expect(pipeline.submitted).toEqual([]);
  });
});

describe("registerKind：登记不等于放行", () => {
  it("登记进清单且默认未确认；label 缺省回退 id（设置页上宁可显示一串 id 也不显示空白行）", () => {
    const { service } = assemble();
    service.registerKind({ id: "svc-face:a", label: "A 插件" });
    service.registerKind({ id: "svc-face:b", label: "" });
    expect(listKinds()).toContainEqual({ id: "svc-face:a", label: "A 插件", confirmed: false });
    expect(listKinds()).toContainEqual({ id: "svc-face:b", label: "svc-face:b", confirmed: false });
  });

  it("装配时已在 allowKinds 里的种类直接是已确认", () => {
    const { service } = assemble(["svc-face:pre"]);
    service.registerKind({ id: "svc-face:pre", label: "预确认" });
    expect(listKinds()).toContainEqual({ id: "svc-face:pre", label: "预确认", confirmed: true });
  });

  // 清单顺序就是设置页的展示顺序（注册表注释自称如此），而重复登记是插件重载/热更新下的常态：
  // 取先登记的 label 会让用户看到过期的名字，把新登记项插到前面会让列表每次重载都跳一下。
  it("同 id 重复登记取后者的 label 且保持首次登记的位置：清单顺序 = 登记顺序", () => {
    const { service } = assemble();
    // 注册表跨用例累积（没有重置口），故按本用例独有的命名空间过滤后判相对顺序。
    service.registerKind({ id: "svc-order:a", label: "先登记" });
    service.registerKind({ id: "svc-order:b", label: "后登记" });
    service.registerKind({ id: "svc-order:a", label: "后改的展示名" });

    expect(listKinds().filter((kind) => kind.id.startsWith("svc-order:"))).toEqual([
      { id: "svc-order:a", label: "后改的展示名", confirmed: false },
      { id: "svc-order:b", label: "后登记", confirmed: false },
    ]);
  });

  it("守卫：无冒号 / 命名空间撞内置 / id 非字符串 一律抛错而不是静默忽略", () => {
    const { service } = assemble();
    expect(() =>
      service.registerKind(untyped<RegisterInput>({ id: "no-colon", label: "x" })),
    ).toThrow(/id 非法/u);
    // `:x` 的冒号位置在头部：命名空间是空串，它在设置页上是一行没有归属人的种类。
    expect(() => service.registerKind(untyped<RegisterInput>({ id: ":x", label: "x" }))).toThrow(
      /id 非法/u,
    );
    expect(() =>
      service.registerKind(untyped<RegisterInput>({ id: "ask:foo", label: "x" })),
    ).toThrow(/命名空间/u);
    expect(() => service.registerKind(untyped<RegisterInput>({ id: 42, label: "x" }))).toThrow(
      /需要一个/u,
    );
  });
});

describe("清单与确认：确认态住在设置里，注册表随进程生灭", () => {
  it("确认写整份名单（去重），撤销从名单里移除", async () => {
    const { service, config } = assemble(["svc-face:c", "svc-keep:other"]);
    service.registerKind({ id: "svc-face:c", label: "C" });
    expect(listKinds()).toContainEqual({ id: "svc-face:c", label: "C", confirmed: true });

    // 撤销一个不能顺手清掉别人：名单是整份写回的，过滤条件写错就是「撤销 A 之后 B 也失效」。
    await confirmKind("svc-face:c", false);
    expect(config.writes).toEqual([{ allowKinds: ["svc-keep:other"] }]);
    expect(listKinds()).toContainEqual({ id: "svc-face:c", label: "C", confirmed: false });

    await confirmKind("svc-face:c", true);
    expect(config.writes[1]).toEqual({ allowKinds: ["svc-keep:other", "svc-face:c"] });
    expect(listKinds()).toContainEqual({ id: "svc-face:c", label: "C", confirmed: true });
  });

  it("重复确认不产生重复条目（写的是整份名单，不是增量）", async () => {
    const { service, config } = assemble(["svc-face:d", "svc-face:d"]);
    service.registerKind({ id: "svc-face:d", label: "D" });
    await confirmKind("svc-face:d", true);
    expect(config.writes).toEqual([{ allowKinds: ["svc-face:d"] }]);
  });

  it("确认未登记的种类抛错（设置端点先查清单给 404，走到这里说明有人绕过了它）", async () => {
    assemble();
    await expect(confirmKind("svc-face:never", true)).rejects.toThrow(/未登记/u);
  });
});

