/**
 * dsh-notifier — 消费方类型编译用例（源码面类型体锚）。
 *
 * 为什么存在：导出面快照门禁（scripts/data/dsh-notifier-export-surface.json）只比对
 * `export declare const/function/class` 块，对 `interface` / `type` 体**零覆盖**（门禁自述的盲区①）
 * ——给 `NotifierService` 加一个方法、改一个字段类型，快照不会红。类型体因此由本文件的锚兜住：
 * 逐个 `Equal` / `Same<T, 独立字面量>`，成员增删与类型漂移即 tsc 红。本文件的编译期锚共 **6 条**。
 *
 * 判据在编译期：本文件由 `test/tsconfig.json`（noEmit）经
 * `scripts/test/service-contract-wiring.test.ts` 的真实 `tsc -p` 编译；Node 直跑（type stripping）
 * 会擦掉类型断言，故下面的运行时断言只是「用例没被绕开」的护栏，不构成判据。
 *
 * 写死期望值的纪律：期望值必须是**独立字面量**。用 `T["m"]` 自引用、或 import 包内未导出的类型当
 * 期望值，会让锚与被测类型同步漂移、退化成恒真。
 *
 * 面口径（#733 M2-3.2）：本文件按**源码面**（`../../src/index.ts`）导入，锚的是类型体；**产物面**
 * （按包名取 `lib/index.d.ts`）的跨包可达性单列在 `consumer-product-face.ts`——声明合并只写进源
 * `.d.ts`、从未进产物这类缺陷只有在产物面才可见（源码面导入会让 `src/index.ts` 直接进编译程序）。
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import type { Context } from "@deepseek-ai/cordis";

import * as entry from "../../src/index.ts";
import type { NotifierApplyConfig, NotifierService } from "../../src/index.ts";
import { apply, inject, name } from "../../src/index.ts";

// ---------------------------------------------------------------- 编译期类型原语

/** 精确相等（含可选性/联合分布）。 */
type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
/**
 * 结构互含（双向子型）。interface 与匿名对象字面量之间存在 TypeScript 表示层边界，`Equal` 会把
 * 语义等价的两者判为不等（误红），故对象结构与函数类型用「双向 extends」替代：删字段 / 改字段类型 /
 * 改联合 / 改方法签名任意单向漂移都会破坏某一方向的子型关系。可选性的等价边缘形态
 * （`a?: T` 与 `a: T | undefined`）不区分，属非破坏性漂移。
 */
type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;
/** 编译期闸门：泛型实参不是 true 就报错。 */
type Expect<T extends true> = T;

// ---------------------------------------------------------------- 期望值（独立字面量）

/** 通知种类词汇表：内置七种 + 外部注册的 `<命名空间>:<id>`。 */
type NotifyKindShape =
  | "ask"
  | "question"
  | "done"
  | "subagent-done"
  | "error"
  | "turn-end"
  | "test"
  | `${string}:${string}`;

/** 展示强度词汇表。 */
type NotifySeverityShape = "info" | "success" | "warning" | "failure";

// ---------------------------------------------------------------- 类型体锚

/** 类型 1/6：NotifierService —— 本插件对兄弟插件开放的全部能力面。 */
type _NotifierServiceShape = Expect<
  Same<
    NotifierService,
    {
      readonly apiVersion: 2;
      registerKind(registration: { id: `${string}:${string}`; label: string }): void;
      send(request: {
        kind: NotifyKindShape;
        severity?: NotifySeverityShape;
        title?: string;
        body: string;
      }): Promise<void>;
    }
  >
>;

/** 类型 2/6：NotifierApplyConfig —— 组合层入口配置（interface，快照门禁的盲区①，靠本文件兜住）。 */
type _NotifierApplyConfigShape = Expect<Same<NotifierApplyConfig, { enabled?: boolean }>>;

/** 类型 3/6：apply 签名 —— 消费方经 cordis patch 调用的那个入口。 */
type _ApplyShape = Expect<
  Same<typeof apply, (ctx: Context, config?: { enabled?: boolean }) => void>
>;

/** 类型 4/6：inject —— 依赖的宿主服务清单。 */
type _InjectShape = Expect<Equal<typeof inject, string[]>>;

/** 类型 5/6：name —— 稳定的 cordis 插件名。 */
type _NameShape = Expect<Equal<typeof name, "notifier">>;

/** 类型 6/6：声明合并的槽位类型就是服务面（改一面不改另一面即红）。 */
type _ServiceSlotShape = Expect<Equal<Context["wingsky.notifier"], NotifierService>>;

// ---------------------------------------------------------------- 编译期语句探针
// 只在编译期存在：运行时不调用它们（`declare` / 未调用函数体），故不会在 vitest 里执行到。

/** 消费方视角的读法：`ctx` 上的服务槽必须直接可用。 */
function _serviceFromContext(ctx: Context): NotifierService {
  return ctx["wingsky.notifier"];
}

/** 授权边界（`@ts-expect-error` 指令本身受检：错误消失即报 unused）。 */
function _rejectedByType(service: NotifierService): void {
  // @ts-expect-error 确认是设置页的授权动作，不在对外服务面上
  service.confirmKind("demo:report", true);
  // @ts-expect-error 清单同理
  service.listKinds();
}

// ---------------------------------------------------------------- 运行时护栏与自述自检

describe("运行时护栏：导出面确实可从包入口取到", () => {
  const baseline: { exports: Array<{ name: string; isType: boolean }> } = JSON.parse(
    readFileSync(
      new URL("../../../../scripts/data/dsh-notifier-export-surface.json", import.meta.url),
      "utf8",
    ),
  );
  const self = readFileSync(new URL("./consumer-types.test.ts", import.meta.url), "utf8");

  it("包入口的运行时导出恰好是快照基线的非类型导出（增删即 ABI 变化）", () => {
    const expected = baseline.exports
      .filter((item) => !item.isType)
      .map((item) => item.name)
      .sort();
    expect(expected.length).toBeGreaterThan(0);
    expect(Object.keys(entry).sort()).toEqual(expected);
  });

  it("宿主依赖清单由运行时值锁定（类型只管它是 string[]，管不到内容）", () => {
    expect(inject).toContain("webServer");
  });

  it("每个导出面类型导出都有一条 <名字>Shape 类型体锚（逐个覆盖不变式）", () => {
    const typeExports = baseline.exports.filter((item) => item.isType).map((item) => item.name);
    expect(typeExports.length).toBeGreaterThan(0);
    expect(typeExports.filter((typeName) => !self.includes(`type _${typeName}Shape = `))).toEqual(
      [],
    );
  });

  it("头部自述与实际一致：锚条数与声明相符", () => {
    const declared = /本文件的编译期锚共 \*\*(\d+) 条\*\*/u.exec(self);
    expect(declared).not.toBeNull();
    const anchors = self.match(/^type _[A-Za-z]+ = Expect</gmu) ?? [];
    // 编号连续性与分母一致性（原先另两条断言）是**自涉**判据：它读的是这份文件自己的注释，
    // 产品代码坏掉也不会红。锚条数这一条才是有效的（漏写一个锚 = 少一条编译期判据）。
    expect(anchors.length).toBe(Number(declared![1]));
  });
});

packages/dsh-notifier/test/unit/events/s.source:
/**
 * dsh-notifier events 域 session 块 —— 从宿主对象上读证据：会话标题、turn/end、子代理归属。
 *
 * 为什么值得单独一测：这三个读取都跨宿主边界读**不受信**的对象（payload 里的 Agent 与会话日志来自
 * 别的模块、别的版本，字段随时可能缺、可能是脏值），而读错一处的症状全是「通知看起来发了但内容不对」：
 * 任务名缺失、子代理完成被报成主任务完成、脏 turn 号把后续真实完成永久吞掉。因此本文件不装配任何
 * 东西，直接喂假 Agent——被读的每一处分支都要能单独说清。
 */
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { SessionEvent } from "@deepseek-ai/dsh-session";
import { describe, expect, it } from "vitest";

import { makeAgentRegistry } from "../../helpers.ts";
import {
  isSubagentOf,
  lastTurnEndOf,
  sessionTitleOf,
  turnEndEvidenceOf,
} from "../../../src/server/events/impl/session/index.ts";

/**
 * 会话日志条目：判定只读 `type` 与 `data`，其余字段（seq / time）与判定无关，故不造。
 * 断言用 `as unknown as` 收口在这里：真实 SessionEvent 带 seq/time/必需性标记，抄一份等于把
 * 官方的信封形状抄成第二份事实源，而本块读的从来只有这么几个字段。
 */
function titleEvent(title: string): SessionEvent {
  return { type: "session/title", data: { title } } as unknown as SessionEvent;
}

function turnEndEvent(turn: unknown, reason: unknown = { kind: "completed" }): SessionEvent {
  return { type: "turn/end", data: { turn, reason } } as unknown as SessionEvent;
}

function unknownEvent(): SessionEvent {
  return { type: "user/message", data: {} } as unknown as SessionEvent;
}

/** 假 agent：只暴露被读的两处（`session.header` 与 `session.snapshotEvents()`）。 */
function makeAgent(
  id: string,
  options: {
    events?: SessionEvent[];
    header?: Record<string, unknown>;
    snapshotThrows?: boolean;
  } = {},
): Agent {
  const events = options.events ?? [];
  return {
    id,
    session: {
      header: options.header ?? {},
      snapshotEvents: () => {
        if (options.snapshotThrows === true) throw new Error("日志读不出来");
        return events;
      },
    },
  } as unknown as Agent;
}

describe("sessionTitleOf：任务名取自日志里最后一条标题", () => {
  it("后写的标题胜出（改名后通知里还显示旧名，用户会以为改名没生效）", () => {
    const agent = makeAgent("s-title", { events: [titleEvent("旧名"), titleEvent("新名")] });
    expect(sessionTitleOf(agent)).toEqual({ found: true, title: "新名" });
  });

  it("trim 后超过 40 字符即截断（系统通知的标题行很短，长标题会挤掉真正要看的内容）", () => {
    const agent = makeAgent("s-long", { events: [titleEvent(`  ${"x".repeat(60)}  `)] });
    expect(sessionTitleOf(agent)).toEqual({ found: true, title: "x".repeat(40) });
  });

  it("空白标题当作没有标题（否则通知里会出现一行「任务「」」）", () => {
    const agent = makeAgent("s-blank", { events: [titleEvent("   ")] });
    expect(sessionTitleOf(agent)).toEqual({ found: false });
  });

  it("日志读不出来时返回「没有标题」而不是抛出（通知主流程不该被一次日志读取失败带走）", () => {
    const agent = makeAgent("s-broken", { snapshotThrows: true });
    expect(sessionTitleOf(agent)).toEqual({ found: false });
  });
});

describe("turnEndEvidenceOf：turn/end 的证据收窄", () => {
  it("正常一条 turn/end 读出轮次与成因", () => {
    expect(turnEndEvidenceOf(turnEndEvent(3, { kind: "completed" }))).toEqual({
      found: true,
      evidence: { turn: 3, kind: "completed" },
    });
  });

  it("非 turn/end 一律不算证据（会话日志里绝大多数追加都不是结束）", () => {
    expect(turnEndEvidenceOf(unknownEvent())).toEqual({ found: false });
  });

  it("turn 不是有限数就丢弃（NaN 一旦进了记账，后续真实完成因 x > NaN 恒假被永久吞掉）", () => {
    for (const turn of [Number.NaN, Number.POSITIVE_INFINITY, "3", undefined, null]) {
      expect(turnEndEvidenceOf(turnEndEvent(turn)), `turn=${String(turn)}`).toEqual({
        found: false,
      });
    }
  });

  it("reason 不是对象就丢弃（脏载荷不能变成一条 kind 为 undefined 的证据）", () => {
    expect(turnEndEvidenceOf(turnEndEvent(3, null))).toEqual({ found: false });
    expect(turnEndEvidenceOf(turnEndEvent(3, "completed"))).toEqual({ found: false });
  });

  it("reason.kind 不是字符串时按空值处理，而不是让 undefined 漏进判定", () => {
    expect(turnEndEvidenceOf(turnEndEvent(3, {}))).toEqual({
      found: true,
      evidence: { turn: 3, kind: "" },
    });
  });
});

describe("lastTurnEndOf：取日志里最新一条结束证据", () => {
  it("倒序扫过尾随的其它追加（turn/end 之后通常还有落盘的事件）", () => {
    const agent = makeAgent("s-last", {
      events: [turnEndEvent(1), turnEndEvent(5, { kind: "completed" }), unknownEvent()],
    });
    expect(lastTurnEndOf(agent)).toEqual({ found: true, evidence: { turn: 5, kind: "completed" } });
  });

  it("日志里一条 turn/end 都没有时返回「没有证据」而不是猜一个", () => {
    const agent = makeAgent("s-none", { events: [unknownEvent()] });
    expect(lastTurnEndOf(agent)).toEqual({ found: false });
  });
});

describe("isSubagentOf：子代理归属判定", () => {
  it("origin 命中即真，不必再问注册表", () => {
    const agent = makeAgent("sub-origin", { header: { origin: "subagent" } });
    expect(isSubagentOf(agent, makeAgentRegistry())).toBe(true);
  });

  it("没有 parentSession 就是主任务", () => {
    const agent = makeAgent("main-root", { header: {} });
    expect(isSubagentOf(agent, makeAgentRegistry())).toBe(false);
  });

  it("父 agent 已消亡（查不到）时判主任务：宁可多报一条 done，也不静默用户自己的任务", () => {
    const agent = makeAgent("fork-orphan", { header: { parentSession: "p-gone" } });
    expect(isSubagentOf(agent, makeAgentRegistry())).toBe(false);
  });

  it("父 agent 在册但不拥有它（用户 fork 主线）时判主任务：header 单信号分不开两种 fork", () => {
    const child = makeAgent("fork-user", { header: { parentSession: "p-live" } });
    const parent = makeAgent("p-live");
    const registry = makeAgentRegistry({ live: [parent], owned: [] });
    expect(isSubagentOf(child, registry)).toBe(false);
  });

  it("父 agent 在册且确由它创建时判子代理（运行时归属是唯一可靠的第二个信号）", () => {
    const child = makeAgent("sub-owned", { header: { parentSession: "p-owner" } });
    const parent = makeAgent("p-owner");
    const registry = makeAgentRegistry({ live: [parent], owned: [["sub-owned", "p-owner"]] });
    expect(isSubagentOf(child, registry)).toBe(true);
  });
});

packages/dsh-notifier/test/unit/api/rout.source:
/**
 * dsh-notifier api 域 route 块 —— 每条浏览器请求都要穿过的三道围栏。
 *
 * 为什么单独一测：围栏是**唯一**的实现（本域是浏览器唯一入口），少一道就是一个洞，而洞的症状不会
 * 出现在功能用例里——非回环请求照样能读到设置、写设置、清历史。故这里逐道断言：回环 → 方法 →
 * 异常收口，且顺序不能颠倒（403 必须早于 405：安全判定不能被方法判定绕过）。
 */
import type { IncomingMessage } from "node:http";
import { describe, expect, it } from "vitest";

import { registerEndpoints, sendJson } from "../../../src/server/api/impl/route/index.ts";
import type { Endpoint, RouteHandler } from "../../../src/server/api/impl/route/type.ts";
import { jsonReq, makeLogger, makeRegister, makeRes, pollUntil } from "../../helpers.ts";

/** 假请求：默认是合法回环请求，`body` 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(
  options: {
    method?: string;
    body?: unknown;
    rawBody?: string;
    remoteAddress?: string;
    host?: string;
  } = {},
): IncomingMessage {
  return jsonReq({
    method: options.method ?? "GET",
    url: "/api/dsh-notifier/config",
    body: options.body,
    rawBody: options.rawBody,
    remoteAddress: options.remoteAddress,
    host: options.host,
  });
}

/** 一个端点组，handler 可替换：围栏用例只关心 handler 有没有被调到。 */
function endpointWith(handler: RouteHandler, methods: Array<"GET" | "POST"> = ["GET"]): Endpoint {
  return {
    path: "/api/dsh-notifier/probe",
    methods: Object.fromEntries(methods.map((method) => [method, handler])),
  };
}

/** 注册一个端点并取回宿主真正会调用的那个 handler。 */
function install(handler: RouteHandler, methods: Array<"GET" | "POST"> = ["GET"]) {
  const hub = makeRegister();
  const logger = makeLogger();
  const disposers = registerEndpoints(hub.register, [endpointWith(handler, methods)], logger);
  return { route: hub.routes[0]!, logger, disposers, hub };
}

describe("回环围栏：非回环一律 403", () => {
  it("局域网来源的请求被拒且 handler 根本不被调用（能读到设置就等于把设置面板暴露给了整个内网）", () => {
    let called = 0;
    const { route } = install(() => {
      called += 1;
    });
    const { res, rec, json } = makeRes();
    route.handler(makeReq({ remoteAddress: "192.168.1.5", host: "192.168.1.5:3080" }), res);
    expect(rec.status).toBe(403);
    expect(json()).toEqual({ error: "forbidden: loopback-only" });
    expect(called).toBe(0);
  });

  it("Host 头指向外部域名时同样被拒（DNS 重绑定：来源地址是回环也不够）", () => {
    let called = 0;
    const { route } = install(() => {
      called += 1;
    });
    const { res, rec } = makeRes();
    route.handler(makeReq({ host: "evil.example.com" }), res);
    expect(rec.status).toBe(403);
    expect(called).toBe(0);
  });
});

describe("方法围栏：表里没有的方法给 405 而不是 404", () => {
  it("支持的方法放行到 handler，且 JSON 响应带 no-store（设置视图被浏览器缓存住 = 页面一直显示旧设置）", () => {
    const { route } = install((_req, res) => {
      sendJson(res, 200, { ok: true });
    });
    const { res, rec, json } = makeRes();
    route.handler(makeReq(), res);
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true });
    expect(rec.headers["content-type"]).toBe("application/json; charset=utf-8");
    expect(rec.headers["cache-control"]).toBe("no-store");
  });

  it.each(["POST", "OPTIONS"])("%s 不在方法表里 → 405，并带 allow 头列出支持的方法", (method) => {
    let called = 0;
    const { route } = install((_req, res) => {
      called += 1;
      sendJson(res, 200, { ok: true });
    });
    const { res, rec, json } = makeRes();
    route.handler(makeReq({ method }), res);
    expect(rec.status).toBe(405);
    expect(rec.headers.allow).toBe("GET");
    expect(json()).toEqual({ error: `method not allowed: ${method}` });
    expect(called).toBe(0);
  });

  it("403 先于 405：非回环 + 非法方法给 403（安全判定不能被方法判定绕过去）", () => {
    const { route } = install((_req, res) => sendJson(res, 200, { ok: true }));
    const { res, rec, json } = makeRes();
    route.handler(
      makeReq({ method: "POST", remoteAddress: "10.0.0.9", host: "10.0.0.9:3080" }),
      res,
    );
    expect(rec.status).toBe(403);
    expect(json()).toEqual({ error: "forbidden: loopback-only" });
  });
});

describe("异常收口：端点失败必须变成一次响应，而不是挂住的连接", () => {
  it("同步抛出 → 500 + 失败体，并记一条 warn（漏出去的异常留下的不是错误页，是挂住的连接）", () => {
    const { route, logger } = install(() => {
      throw new Error("读设置炸了");
    });
    const { res, rec, json } = makeRes();
    route.handler(makeReq(), res);
    expect(rec.status).toBe(500);
    expect(json()).toEqual({ ok: false, error: { error: "读设置炸了" } });
    expect(logger.warns).toHaveLength(1);
    expect(logger.warns[0]).toContain("读设置炸了");
  });

  it("异步端点 reject 也被收口（异步端点的异常否则会变成未捕获拒绝）", async () => {
    const { route, logger } = install(async () => {
      throw new Error("写盘炸了");
    });
    const { res, rec, json } = makeRes();
    route.handler(makeReq(), res);
    expect(rec.status).toBe(0);
    await pollUntil(() => rec.status === 500, "异步端点失败被收口为 500");
    expect(json()).toEqual({ ok: false, error: { error: "写盘炸了" } });
    expect(logger.warns[0]).toContain("写盘炸了");
  });

  it("响应头已发出后失败只记日志不重写头（重复写会抛 ERR_HTTP_HEADERS_SENT，把端点失败升级成宿主侧未捕获异常）", () => {
    const { route, logger } = install((_req, res) => {
      sendJson(res, 200, { ok: true });
      throw new Error("晚到的失败");
    });
    const { res, rec, json } = makeRes();
    route.handler(makeReq(), res);
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true });
    expect(logger.warns[0]).toContain("晚到的失败");
  });
});

describe("注册与摘除", () => {
  it("摘除器与端点一一对应：宿主收回路由靠它，漏一个就是卸载后路由还在", () => {
    const hub = makeRegister();
    const disposers = registerEndpoints(
      hub.register,
      [
        endpointWith((_req, res) => sendJson(res, 200, {})),
        {
          path: "/api/dsh-notifier/other",
          methods: { GET: (_req, res) => sendJson(res, 200, {}) },
        },
      ],
      makeLogger(),
    );
    expect(disposers).toHaveLength(2);
    for (const dispose of disposers) dispose();
    expect(hub.disposed).toEqual(["/api/dsh-notifier/probe", "/api/dsh-notifier/other"]);
  });
});

packages/dsh-notifier/test/unit/api/kind.source:
/**
 * dsh-notifier api 域 kinds 块 —— GET /kinds 与 POST /kinds（动态种类清单与用户确认）。
 *
 * 判据面：本块自己只判两件事——**存在性**（未登记 → 404，且不去动设置）与**结果码映射**
 * （与设置端点同款：invalid 400 / conflict 409 / unavailable 503）。确认的写入语义归 sdk 域，
 * 不在这里重测；这里守的是「端点如何把 sdk 的答复翻译成 HTTP」——两个端点上对同一件事给出
 * 不同答复，会让客户端被迫按路径分叉处理同一件事。
 */
import type { IncomingMessage } from "node:http";
import { describe, expect, it } from "vitest";

import type { KindPort } from "../../../src/server/api/deps.ts";
import { KindsEndpoints } from "../../../src/server/api/impl/kinds/index.ts";
import { jsonReq, makeRes } from "../../helpers.ts";

/** 写面结果经能力面的签名可达，不请 sdk 域再多导出一个名字。 */
type ConfirmResult = Awaited<ReturnType<KindPort["confirmKind"]>>;
type RegisteredKind = ReturnType<KindPort["listKinds"]>[number];

const REGISTERED: RegisteredKind[] = [
  { id: "demo:x", label: "X 插件", confirmed: false },
  { id: "demo:y", label: "Y 插件", confirmed: true },
];

/** 假请求：body 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(options: { body?: unknown; rawBody?: string } = {}): IncomingMessage {
  return jsonReq({ method: "POST", url: "/api/dsh-notifier/kinds", ...options });
}

/** 假 sdk 管理面：清单给固定两条，确认记账并按用例指定的结果作答。 */
function fakeKinds(result?: ConfirmResult, listed: RegisteredKind[] = REGISTERED) {
  const confirmed: Array<{ id: string; confirmed: boolean }> = [];
  const port: KindPort = {
    listKinds: () => [...listed],
    confirmKind: async (id, value) => {
      confirmed.push({ id, confirmed: value });
      return (
        result ?? {
          ok: true,
          view: { user: {}, revision: 12, writable: true, effective: {} },
        }
      );
    },
  };
  return { port, confirmed };
}

/** GET 一次清单。 */
function get(listed: RegisteredKind[] = REGISTERED) {
  const kinds = fakeKinds(undefined, listed);
  const { res, rec, json } = makeRes();
  new KindsEndpoints(kinds.port).read(makeReq(), res);
  return { rec, json, kinds };
}

/** POST 一次确认。 */
async function post(request: { body?: unknown; rawBody?: string }, result?: ConfirmResult) {
  const kinds = fakeKinds(result);
  const { res, rec, json } = makeRes();
  await new KindsEndpoints(kinds.port).confirm(makeReq(request), res);
  return { rec, json, kinds };
}

describe("GET /kinds：清单是登记项 × 确认态", () => {
  it("回 `kinds` 清单（设置页据此渲染「允许 / 拒绝」，缺了确认态按钮就无从着色）", () => {
    const { rec, json } = get();
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true, kinds: REGISTERED });
  });
});

describe("POST /kinds：存在性在本块判", () => {
  it("已登记 + 确认成功 → 200，成功体带回新修订号与更新后的清单", async () => {
    const { rec, json, kinds } = await post({ body: { kind: "demo:x", confirmed: true } });
    expect(rec.status).toBe(200);
    expect(kinds.confirmed).toEqual([{ id: "demo:x", confirmed: true }]);
    expect(json()).toEqual({ ok: true, kinds: REGISTERED, revision: 12 });
  });

  it("未登记的种类 → 404 且不写设置（存在性判在写面之前，否则设置里会多出一个查不到归属的键）", async () => {
    const { rec, json, kinds } = await post({ body: { kind: "demo:never", confirmed: true } });
    expect(rec.status).toBe(404);
    expect(json()).toEqual({
      ok: false,
      error: { code: "not-found", details: "未注册的动态种类: demo:never" },
    });
    expect(kinds.confirmed).toEqual([]);
  });

  it.each<[string, unknown]>([
    ["kind 缺席", { confirmed: true }],
    ["kind 是空串", { kind: "", confirmed: true }],
    ["kind 不是字符串", { kind: 42, confirmed: true }],
    ["confirmed 缺席", { kind: "demo:x" }],
    ["confirmed 不是布尔", { kind: "demo:x", confirmed: "yes" }],
  ])("参数非法（%s）→ 400 且不写设置", async (_label, body) => {
    const { rec, json, kinds } = await post({ body });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid", details: "需为 { kind: string, confirmed: boolean }" },
    });
    expect(kinds.confirmed).toEqual([]);
  });

  it("请求体不是合法 JSON 对象 → 400 invalid-json", async () => {
    const { rec, json, kinds } = await post({ rawBody: "不是 JSON" });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: {
        code: "invalid-json",
        details: "请求体不是合法 JSON 对象（或超出大小上限）",
      },
    });
    expect(kinds.confirmed).toEqual([]);
  });
});

describe("POST /kinds：写面四态 → 四个状态码（与设置端点同款映射）", () => {
  // 第四态（写入异常 → 500）由路由层的异常收口承担（`api/route.test.ts` 的两条 500 用例）；
  // 端点这一半的契约是「不吞异常」，吞掉会让原因进不了日志、用户只看到 503。
  it("写面抛错 → 端点不吞，异常交给路由层收口成 500", async () => {
    const port: KindPort = {
      listKinds: () => [...REGISTERED],
      confirmKind: async () => {
        throw new Error("写盘炸了");
      },
    };
    const { res } = makeRes();
    await expect(
      new KindsEndpoints(port).confirm(makeReq({ body: { kind: "demo:x", confirmed: true } }), res),
    ).rejects.toThrow("写盘炸了");
  });

  it("invalid → 400，带出错的键与提示", async () => {
    const { rec, json } = await post(
      { body: { kind: "demo:x", confirmed: true } },
      { ok: false, reason: "invalid", error: { key: "allowKinds", hint: "需要种类 id 数组" } },
    );
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { error: "配置校验失败: allowKinds", hint: "需要种类 id 数组" },
    });
  });

  it("conflict → 409 且带 SETTINGS_CONFLICT", async () => {
    const { rec, json } = await post(
      { body: { kind: "demo:x", confirmed: true } },
      { ok: false, reason: "conflict" },
    );
    expect(rec.status).toBe(409);
    expect(json()).toEqual({
      ok: false,
      error: { error: "版本冲突", code: "SETTINGS_CONFLICT" },
    });
  });

  it("unavailable → 503", async () => {
    const { rec, json } = await post(
      { body: { kind: "demo:x", confirmed: true } },
      { ok: false, reason: "unavailable" },
    );
    expect(rec.status).toBe(503);
    expect(json()).toEqual({
      ok: false,
      error: { error: "设置服务不可用", code: "settings-unavailable" },
    });
  });
});

packages/dsh-notifier/test/unit/channels.source:
/**
 * dsh-notifier channels 域 deliver 块 —— 投递编排的 fail-soft 与展示上限。
 *
 * 判据为什么落在这里：出口承诺「失败是返回值，不是异常」，而 `deliver` 是唯一能证明这句承诺被
 * 守住的地方——一次拒绝若冒给 `Promise.all`，整批一起失败，调用方只能记一条「全都没发出去」。
 * 上限表同住一块：出口与编排共用同一份，改错一个数字同时影响所有出口的截断。
 * 出口一律用本地假目标：真出口要发网络 / 起子进程，而本块要守的是编排语义，不是出口行为。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { deliver } from "../../../src/server/channels/interface.ts";
import type {
  DeliveryTarget,
  NotifyFrame,
  NotifyMessage,
} from "../../../src/server/channels/interface.ts";
import {
  FAILURE_REASON_MAX,
  displayCaps,
  truncateCodePoints,
} from "../../../src/server/channels/impl/deliver/caps.ts";
import { pollUntil, stubFetch, wire } from "../../helpers.ts";

/** 待投递消息：`ts` 写死不取 `Date.now()`，免得断言跟着运行时刻漂。 */
function messageOf(over: Partial<NotifyMessage> = {}): NotifyMessage {
  return { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

/** 待兑现的 promise：用来制造「上一个出口还挂着」的现场。 */
function deferred<T>(): { promise: Promise<T>; resolve: (value: T) => void } {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((settle) => {
    resolve = settle;
  });
  return { promise, resolve };
}

/** 一个浏览器出口目标：`emitFrame` 由本用例给，用来观测编排何时触达出口。 */
function browserTarget(emitFrame: (frame: NotifyFrame) => void): DeliveryTarget {
  return { type: "browser", popup: true, sound: false, whenVisible: false, emitFrame };
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("deliver：并发投递，逐目标 fail-soft", () => {
  // 一个出口卡住（bark 的硬超时是 10s）不该把同批的系统通知一起压住。
  it("一个出口卡住不拖住同批其它出口（串行 await 会让 10s 超时的 bark 压住系统通知）", async () => {
    const gate = deferred<Response>();
    const calls: string[] = [];
    vi.stubGlobal("fetch", (input: unknown) => {
      const url = String(input);
      calls.push(url);
      const response = url.endsWith("/slow")
        ? gate.promise
        : Promise.resolve(new Response("{}", { status: 200 }));
      return response;
    });

    const pending = deliver(messageOf(), [
      { type: "bark", baseUrl: "http://127.0.0.1:40281/slow", deviceKey: "dk" },
      { type: "bark", baseUrl: "http://127.0.0.1:40281/fast", deviceKey: "dk" },
    ]);
    await pollUntil(() => calls.length === 2, "快出口应在慢出口返回之前就发出");
    gate.resolve(new Response("{}", { status: 200 }));
    expect((await pending).map((result) => result.status)).toEqual(["ok", "ok"]);
  });

  // 违约若冒给 Promise.all，真实到达的出口也一起背锅，调用方只能记一条「全都没发出去」。
  it("出口违约被收成本条失败，不牵连同批其它出口；结果与 targets 同序（错位等于把失败记到别人头上）", async () => {
    const emitted: NotifyFrame[] = [];
    const results = await deliver(messageOf(), [
      browserTarget(() => {
        throw new Error("帧出口已断开");
      }),
      browserTarget((frame) => {
        emitted.push(frame);
      }),
    ]);
    // 违约的出口没给出任何证据，故 stage 取 accepted；再投一次只是把同一个洞踩第二遍，故不可重试。
    expect(results[0]).toEqual({
      status: "failed",
      stage: "accepted",
      reason: { code: "reasonChannelThrew", detail: "帧出口已断开" },
      retryable: false,
    });
    expect(results[1]).toEqual({ status: "ok", stage: "accepted" });
    expect(emitted).toHaveLength(1);
  });

  // 未知出口类型若落成空元素，下游读 `result.status` 会当场 TypeError，整批结果连同一起来到
  // 这一步的出口一起丢；跨边界值不受编译期联合约束，故判的是这一侧的行为。
  it("未知投递目标类型：该目标收成一条失败明细，其余目标照常投递，结果里不出现空元素", async () => {
    const emitted: NotifyFrame[] = [];
    const results = await deliver(messageOf(), [
      wire<DeliveryTarget>({ type: "slack" }),
      browserTarget((frame) => {
        emitted.push(frame);
      }),
    ]);

    expect(results).toHaveLength(2);
    expect(results[0]).toEqual({
      status: "failed",
      stage: "accepted",
      reason: { code: "reasonUnknownTarget", params: { kind: "slack" } },
      retryable: false,
    });
    expect(results[1]).toEqual({ status: "ok", stage: "accepted" });
    expect(emitted).toHaveLength(1);
  });

  // 派发表漏一个 case，那个出口的目标会被判成「未知类型」——用户看到的是「webhook 频道永远失败」。
  it("webhook 目标经派发表走到出口：真发出请求并回报出口的结论（漏 case 即该出口永远失败）", async () => {
    const calls = stubFetch(() => new Response("{}", { status: 200 }));
    const results = await deliver(messageOf(), [
      { type: "webhook", url: "http://127.0.0.1:40281/hook", preset: "raw" },
    ]);

    expect(results).toEqual([{ status: "ok", stage: "delivered" }]);
    expect(calls).toHaveLength(1);
    expect(calls[0]!.method).toBe("POST");
  });
});

describe("展示上限：码点口径与逐出口数值", () => {
  // 按 UTF-16 截会腰斩 emoji：屏幕上出现替换符，等于用户看到的内容被改坏。
  it("按码点截断：emoji 代理对不会被腰斩成替换符（按 UTF-16 切会留下孤立高位代理）", () => {
    expect(truncateCodePoints("🙂🙂", 1)).toBe("🙂");
    expect(truncateCodePoints("🙂".repeat(64), 64)).toBe("🙂".repeat(64));
  });

  // 上限是各外部系统容忍度的编码，改宽一处就会让某个出口收到它显示不了的长度。
  it("上限表是外部系统容忍度的编码：system 正文只有 256，webhook/bark 4096，页面 2048", () => {
    expect(displayCaps.system).toEqual({ titleMax: 64, bodyMax: 256 });
    expect(displayCaps.bark).toEqual({ titleMax: 64, bodyMax: 4096 });
    expect(displayCaps.webhook).toEqual({ titleMax: 64, bodyMax: 4096 });
    expect(displayCaps.browser).toEqual({ titleMax: 64, bodyMax: 2048 });
    // 失败原因上限的唯一独立锚点：出口那两处是「用常量截、用常量量」，只有钉住字面量才能
    // 发现常量本身被改宽（状态页只显示一行，改宽即撑坏）。
    expect(FAILURE_REASON_MAX).toBe(300);
  });
});

packages/dsh-notifier/test/unit/shared/r.source:
/**
 * dsh-notifier shared 域 —— 投递理由的结构化形态（#782 批 1）。
 *
 * 判据面：这一层是**跨端线格式**的定义处，服务端写盘、客户端渲染、升级链割接都读同一份口径。
 * 规范化的容错边界错一格，症状是历史页显示 `undefined`（读太严）或把半截值透传到界面（读太松）。
 */
import { describe, expect, it } from "vitest";

import {
  REASON_LEGACY,
  clampReasonDetail,
  normalizeReason,
  reason,
  reasonFromCause,
  sameReasonShape,
} from "../../../src/server/shared/interface.ts";

describe("reason：生产侧构造", () => {
  it("只写取到的键（缺 params / detail 时不留空壳）", () => {
    expect(reason("reasonSkipConfig")).toEqual({ code: "reasonSkipConfig" });
    expect(reason("reasonBarkHttp", { params: { status: 503 } })).toEqual({
      code: "reasonBarkHttp",
      params: { status: 503 },
    });
    // 空 detail 与没有 detail 是同一件事：界面上都是「没有原文可展开」
    expect(reason("reasonChannelThrew", { detail: "" })).toEqual({ code: "reasonChannelThrew" });
  });

  it("参数只收标量：嵌套值留不下来（文案层不必再判嵌套）", () => {
    // 跨边界值不受编译期约束：用读侧入口喂一个带嵌套参数的对象，验证过滤发生在共享层。
    expect(
      normalizeReason({ code: "reasonBarkHttp", params: { status: 500, nested: { a: 1 } } }),
    ).toEqual({ code: "reasonBarkHttp", params: { status: 500 } });
  });
});

describe("normalizeReason：读侧归一化", () => {
  // 升级前的行、手改的文件都会走到这里：字符串按整句原文收编，不猜它的 code。
  it("散文（字符串）收编成 reasonLegacy + detail", () => {
    expect(normalizeReason("连接超时")).toEqual({ code: REASON_LEGACY, detail: "连接超时" });
    expect(normalizeReason("")).toBeUndefined();
  });

  it("结构化对象只取认识的三个字段（陌生键与非法参数类型都丢掉）", () => {
    expect(
      normalizeReason({
        code: "reasonBarkHttp",
        params: { status: 400, bad: { x: 1 } },
        detail: "boom",
        extra: "不该留下",
      }),
    ).toEqual({ code: "reasonBarkHttp", params: { status: 400 }, detail: "boom" });
  });

  it("读不出的形态一律 undefined：null / 数组 / 没有 code / 空 code", () => {
    expect(normalizeReason(null)).toBeUndefined();
    expect(normalizeReason([])).toBeUndefined();
    expect(normalizeReason(42)).toBeUndefined();
    expect(normalizeReason({})).toBeUndefined();
    expect(normalizeReason({ code: "" })).toBeUndefined();
    expect(normalizeReason({ code: 7 })).toBeUndefined();
  });

  // 认不出的 code 仍然保留：跨版本的数据不该被本版的闭集裁掉，渲染侧对它做中性回退。
  it("不认识的 code 原样保留（读侧开放，闭集只管生产侧）", () => {
    expect(normalizeReason({ code: "reasonFromTheFuture" })).toEqual({
      code: "reasonFromTheFuture",
    });
  });

  it("幂等：归一化过的值再归一化一次逐字不变", () => {
    const once = normalizeReason({ code: "reasonBarkHttp", params: { status: 401 }, detail: "x" });
    expect(normalizeReason(once)).toEqual(once);
  });
});

describe("reasonFromCause / reasonEquals / clampReasonDetail", () => {
  // 抛出物不一定是 Error（跨边界值）：原因若印成 undefined，日志里就只剩「失败」两个字。
  it("reasonFromCause：Error 取 message，非 Error 取 String，都进 detail 且不做主文案", () => {
    expect(reasonFromCause("reasonChannelThrew", new Error("出口实现违约"))).toEqual({
      code: "reasonChannelThrew",
      detail: "出口实现违约",
    });
    expect(reasonFromCause("reasonChannelThrew", "裸抛出物")).toEqual({
      code: "reasonChannelThrew",
      detail: "裸抛出物",
    });
  });

  // 割接用它判「这条已经改过形了」：判松了会反复改写同一行，判成语义等价则割接变空操作。
  it("sameReasonShape：判的是形态不是语义——旧散文与它的收编形态**判不等**（否则割接不生效）", () => {
    const produced = reason("reasonBarkHttp", { params: { status: 401 }, detail: "nope" });
    expect(sameReasonShape(produced, produced)).toBe(true);
    // 同一形态的另一份对象也算（割接重跑不该因为对象身份不同就再写一次盘）
    expect(sameReasonShape({ ...produced }, produced)).toBe(true);
    // params 进判据：只看 code+detail 的旧写法会把「带参数但已割接」的条目再写一次盘
    expect(sameReasonShape({ ...produced, params: { status: 402 } }, produced)).toBe(false);
    expect(sameReasonShape({ code: "reasonBarkHttp", detail: "nope" }, produced)).toBe(false);
    // 关键一格：语义等价但不是同一个形态 —— 必须判不等，否则旧数据永远不会被割接
    expect(sameReasonShape("旧散文", { code: REASON_LEGACY, detail: "旧散文" })).toBe(false);
    expect(
      sameReasonShape(
        { code: REASON_LEGACY, detail: "旧散文" },
        { code: REASON_LEGACY, detail: "旧散文" },
      ),
    ).toBe(true);
    // 字符串、null、数组都不算结构化形态
    expect(sameReasonShape(null, produced)).toBe(false);
    expect(sameReasonShape([], produced)).toBe(false);
  });

  // 截断是展示语义：超长原文不砍会把设置页撑坏，砍错档位会丢掉定位用的尾部。
  it("clampReasonDetail 按码点截断 detail，无 detail 时原样返回同一个对象", () => {
    expect(
      clampReasonDetail({ code: "reasonChannelThrew", detail: "长".repeat(400) }, 300),
    ).toEqual({
      code: "reasonChannelThrew",
      detail: "长".repeat(300),
    });
    const untouched = { code: "reasonSkipConfig" } as const;
    expect(clampReasonDetail(untouched, 300)).toBe(untouched);
    const short = { code: "reasonChannelThrew", detail: "短" } as const;
    expect(clampReasonDetail(short, 300)).toBe(short);
  });
});

packages/dsh-notifier/test/unit/upgrade/.source:
/**
 * dsh-notifier upgrade 域 steps 块 —— 0.2.3 → 0.2.4 的存储布局归位。
 *
 * 判据面：这是唯一**动用户数据**的一步。搬错的表现是静默丢数据——历史读空、状态表回默认、旧文件
 * 留在 home 根目录，而用户只会看到「通知记录没了」。故逐条锁：内容逐字保留、旧文件留痕、
 * 目标已存在时**不覆盖**（用户可能已经在新位置改过东西）、重跑不累积归档。
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import {
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  legacyFile,
  notifierFile,
} from "../../../src/server/shared/interface.ts";
import { migrateStorageLayout } from "../../../src/server/upgrade/impl/steps/storage-layout.ts";
import { tempDshHome } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原并删除。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

/** 建一个隔离 DSH_HOME（迁移的读端与写端都从它解析路径）。 */
function isolatedHome(): string {
  const home = tempDshHome();
  cleanups.push(home.dispose);
  return home.dir;
}

function writeLegacy(name: string, text: string): void {
  writeFileSync(legacyFile(name), text, "utf8");
}

/** 旧文件名 → 新文件名 → 一份有代表性的内容（jsonl 是多行、json 是单行、seq 是数字）。 */
const ENTRIES = [
  ["dsh-notifier-history.jsonl", HISTORY_FILE_NAME, '{"ts":1,"kind":"done"}\n{"ts":2}\n'],
  [
    "dsh-notifier-status.json",
    STATUS_FILE_NAME,
    '{"bark:main":{"lastTs":9,"lastStatus":"ok","failStreak":0}}\n',
  ],
  ["notifier-seq.json", SEQ_FILE_NAME, "7\n"],
] as const;

describe("旧文件归位", () => {
  it.each(ENTRIES)(
    "%s 搬成新布局的 %s：内容逐字保留，旧文件改名留痕",
    (legacyName, targetName, text) => {
      isolatedHome();
      writeLegacy(legacyName, text);

      migrateStorageLayout();

      expect(readFileSync(notifierFile(targetName), "utf8")).toBe(text);
      expect(existsSync(legacyFile(legacyName))).toBe(false);
      expect(readFileSync(`${legacyFile(legacyName)}.migrated.bak`, "utf8")).toBe(text);
    },
  );

  it("没有旧文件时也把初始形态落定（目标不存在会让「这一份处理过了」的判据永远不成立）", () => {
    isolatedHome();
    migrateStorageLayout();

    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe("");
    expect(readFileSync(notifierFile(STATUS_FILE_NAME), "utf8")).toBe("{}\n");
    // 序号文件的初始形态与流侧落盘同形（流侧写 `${seq}\n`）：首次读取要得到 0。
    expect(readFileSync(notifierFile(SEQ_FILE_NAME), "utf8")).toBe("0\n");
  });

  it("目标已存在时只归档旧文件、不覆盖目标（用户可能已经在新位置改过东西，拿历史盖回去就是用旧盖新）", () => {
    const home = isolatedHome();
    mkdirSync(dirname(notifierFile(HISTORY_FILE_NAME)), { recursive: true });
    writeFileSync(notifierFile(HISTORY_FILE_NAME), '{"ts":99}\n', "utf8");
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');

    migrateStorageLayout();

    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe('{"ts":99}\n');
    expect(readFileSync(`${legacyFile("dsh-notifier-history.jsonl")}.migrated.bak`, "utf8")).toBe(
      '{"ts":1}\n',
    );
    expect(readdirSync(home)).toContain("dsh-notifier-history.jsonl.migrated.bak");
  });

  it("重跑不累积归档名（旧文件第一次就改成了固定后缀，第二次已无源文件可归档）", () => {
    const home = isolatedHome();
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');

    migrateStorageLayout();
    migrateStorageLayout();

    expect(readdirSync(home).filter((name) => name.endsWith(".migrated.bak"))).toEqual([
      "dsh-notifier-history.jsonl.migrated.bak",
    ]);
    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe('{"ts":1}\n');
  });

  it("旧文件读不出来即抛（迁移没做完而启动照常，等于让各域按错误的形态去读数据）", () => {
    isolatedHome();
    // 同名目录：路径存在但没有可读内容——「搬不动」不能被当成「没有旧数据」。
    mkdirSync(legacyFile("dsh-notifier-history.jsonl"), { recursive: true });

    expect(() => migrateStorageLayout()).toThrow(/旧存储文件不可读/u);
  });

  // 归档是「这一份处理过了」的标记：改名失败却继续，旧数据就悬在两套布局之间（新位置有了副本，
  // 归档标记却没有），而用户看到的是「迁移成功」。
  it("旧文件改名失败即抛（归档没成功就不能算这一步做完了）", () => {
    isolatedHome();
    const legacy = legacyFile("dsh-notifier-history.jsonl");
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');
    // 归档目标被非空目录占住：rename 覆盖不了它。
    mkdirSync(`${legacy}.migrated.bak`, { recursive: true });
    writeFileSync(join(`${legacy}.migrated.bak`, "占位"), "", "utf8");

    expect(() => migrateStorageLayout()).toThrow(/旧存储文件改名失败/u);
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 finalize 块 —— 请求加工成待投递消息。
 *
 * 判据为什么是这些：
 *  - 强度缺省按 kind 补齐，外部 kind 则**缺席**而不是补一个中间档：出口的缺省路径已经定义了
 *    「未提供」的语义，这里再补一套就是第二个默认值来源；
 *  - 标题按码点截断、正文不截断：正文长度权威在各出口自己那里（bark 4096 / 页面 2048 /
 *    系统通知 256），在这里截会把系统通知的上限强加给所有出口。
 */
import { describe, expect, it } from "vitest";

import { finalizeRequest } from "../../../src/server/pipeline/impl/finalize/index.ts";
import { BUILTIN_KINDS } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { BuiltinKind } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/impl/service/type.ts";
import type { NotifySeverity } from "../../../src/server/pipeline/deps.ts";
import { wire } from "../../helpers.ts";

/**
 * 内置 kind → 缺省强度。独立写一遍而不是从源码导：值表漂移必须在这里红，抄源码就恒真了。
 * 表的完整性由「种类逐个对齐 `BUILTIN_KINDS`」那一条兜住。
 */
const KIND_SEVERITY_EXPECTED: ReadonlyArray<readonly [BuiltinKind, NotifySeverity]> = [
  ["ask", "warning"],
  ["question", "info"],
  ["done", "success"],
  ["subagent-done", "info"],
  ["error", "failure"],
  ["turn-end", "info"],
  ["test", "info"],
];

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

describe("finalizeRequest", () => {
  // 缺省强度串了档，用户看到的呈现与事件严重性不符（error 看起来像普通提示）。
  it("内置 kind 补缺省强度：error 必须是 failure（出错通知显示成普通提示就白通知了）", () => {
    for (const [kind, severity] of KIND_SEVERITY_EXPECTED) {
      expect(finalizeRequest(requestOf({ kind }), 1).severity, kind).toBe(severity);
    }
    expect(KIND_SEVERITY_EXPECTED.map(([kind]) => kind).sort()).toEqual([...BUILTIN_KINDS].sort());
  });

  // 非法强度被当成合法值传给出口，对端会收到它不认识的档位。
  it("调用方显式给的强度优先；非法强度视同未提供，回落 kind 缺省", () => {
    expect(finalizeRequest(requestOf({ kind: "error", severity: "info" }), 1).severity).toBe(
      "info",
    );
    expect(
      finalizeRequest(requestOf({ kind: "error", severity: wire<NotifySeverity>("critical") }), 1)
        .severity,
    ).toBe("failure");
  });

  // 给外部 kind 补一个「中间档」，等于替调用方决定了它没说的语义。
  it("外部 kind 没有缺省强度：不写 severity 键，调用方说了才写", () => {
    expect("severity" in finalizeRequest(requestOf({ kind: "demo:report" }), 1)).toBe(false);
    expect(
      finalizeRequest(requestOf({ kind: "demo:report", severity: "warning" }), 1).severity,
    ).toBe("warning");
    expect(
      "severity" in
        finalizeRequest(requestOf({ kind: "demo:report", severity: wire<NotifySeverity>("x") }), 1),
    ).toBe(false);
  });

  // 在定稿层截正文会把系统通知的 256 上限强加给所有出口，用户的正文被提前砍掉。
  it("标题按 64 码点截断且不腰斩 emoji；正文原样透传（长度权威在各出口）", () => {
    expect(
      Array.from(finalizeRequest(requestOf({ title: "题".repeat(65) }), 1).title),
    ).toHaveLength(64);
    const emoji = "🙂".repeat(64);
    expect(finalizeRequest(requestOf({ title: emoji }), 1).title).toBe(emoji);
    const longBody = "文".repeat(5000);
    expect(finalizeRequest(requestOf({ body: longBody }), 1).body).toBe(longBody);
  });

  // ts 或 kind 被改写，历史与投递载荷就对不上号，webhook 的 {{kind}} 也会跟着错。
  it("定稿不改内容：kind 与 ts 原样进消息（webhook 的 {{kind}}、bark 的 levels[kind] 都靠它）", () => {
    const message = finalizeRequest(
      requestOf({ kind: "demo:report", title: "T", body: "B" }),
      1_700_000_000_000,
    );
    expect(message.kind).toBe("demo:report");
    expect(message.ts).toBe(1_700_000_000_000);
    expect(message.title).toBe("T");
    expect(message.body).toBe("B");
  });
});

