/**
 * dsh-notifier config 域 model 块 —— 默认形态与布尔键清单。
 *
 * 为什么默认值要在这里用手写字面量再写一遍：本域其余用例的期望值都取自 `DEFAULT_CONFIG[key]`
 * 本身，而实现的回落源就是同一个对象——两侧同源同变，把 `notifyAsk: true` 改成 `false` 之后
 * 全套测试照样绿。而默认值同时是设置页的初始形态与跨端契约（客户端按同一份形状渲染），
 * 不能是「实现说什么就是什么」：它必须有一份独立于实现的书面形态。
 *
 * `BOOLEAN_KEYS` 同理——它是校验闸门的分支依据，漏登记一个键就等于该键的布尔闸门静默消失
 * （陌生键落到校验的兜底出口即放行），故清单也在测试里手写一份，两边逐字对齐。
 *
 * 本块是 L1 纯函数块，直引 `impl/model/index.ts` 与 `impl/input/index.ts`。
 */
import { describe, expect, it } from "vitest";

import {
  BOOLEAN_KEYS,
  normalizeConfig,
  validateSettings,
} from "../../../src/server/config/impl/input/index.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { RawSettingValue } from "../../../src/server/config/impl/model/type.ts";

/** 手写默认形态：与实现零共享（不 import 它的任何取值），改动默认值必须在这里也显式改一次。 */
const EXPECTED_DEFAULTS = {
  notifyAsk: true,
  notifyQuestion: true,
  notifyTaskDone: true,
  notifySubagentDone: false,
  notifyTaskError: true,
  notifyTurnEnd: false,

  quietHours: { enabled: false, start: "22:00", end: "08:00" },
  // 两条内置频道是默认形态的一部分：读面靠它们才谈得上「与默认表逐字一致」，权威形态也住在它们身上。
  channels: [
    { type: "browser", id: "browser", enabled: true, popup: true, sound: true, whenVisible: false },
    { type: "system", id: "system", enabled: true, popup: true, sound: true },
  ],
  kindRoutes: {},
  allowKinds: [],

  historyMaxAgeDays: 0,
  maxConnections: 16,
} as const;

/** 受布尔闸门管的键：手写清单，与实现的 `BOOLEAN_KEYS` 是两份独立文本。 */
const BOOLEAN_SETTING_KEYS: readonly string[] = [
  "notifyAsk",
  "notifyQuestion",
  "notifyTaskDone",
  "notifySubagentDone",
  "notifyTaskError",
  "notifyTurnEnd",
];

describe("DEFAULT_CONFIG：默认形态以手写字面量为准，不由实现自述", () => {
  it("整份默认设置等于手写形态：布尔偏置、两条内置条目与计数/列表类默认值逐个锚住（改坏一行不该悄无声息）", () => {
    expect(DEFAULT_CONFIG).toEqual(EXPECTED_DEFAULTS);
  });

  it("空输入归一化后与默认表逐字相等：默认表同时是读面的物化基准（两侧不等就说明物化补了默认表没有的东西）", () => {
    expect(normalizeConfig({})).toEqual(DEFAULT_CONFIG);
  });

  it("quietHours 只有 enabled / start / end：allowKinds 缺省表示「时段内不额外放行谁」（整体相等看不出多出来的键值是 undefined）", () => {
    expect(Object.keys(DEFAULT_CONFIG.quietHours)).toEqual(["enabled", "start", "end"]);
    expect("allowKinds" in DEFAULT_CONFIG.quietHours).toBe(false);
  });
});

describe("BOOLEAN_KEYS：布尔闸门的清单必须覆盖每个布尔键", () => {
  it("清单逐字一致，且清单里每个键的非布尔值都被拦下并指向它自己（漏登记一个键 = 该键的闸门静默消失）", () => {
    expect([...BOOLEAN_KEYS].sort()).toEqual([...BOOLEAN_SETTING_KEYS].sort());

    for (const key of BOOLEAN_SETTING_KEYS) {
      const patch: Record<string, RawSettingValue> = { [key]: 1 };
      const verdict = validateSettings(patch);
      if (verdict.ok) throw new Error(`${key} 的非布尔值被判放行`);
      expect(verdict.error.key, key).toBe(key);
      expect(verdict.error.hint, key).toContain("true 或 false");
    }
  });
});

packages/dsh-notifier/test/unit/shared/p.source:
/**
 * dsh-notifier shared 域 paths 块 —— 存储布局与 DSH_HOME 解析。
 *
 * 为什么值得单独一测：文件名是**迁移契约**的一半（升级模块要把旧文件搬到这些名字上），
 * 陈旧路径与陈旧文件名都会静默丢数据——升级读空、旧文件留在原地、用户看到「通知记录没了」。
 * 路径随 `DSH_HOME` 走是另一半：隔离验证与测试换掉该变量即换掉全部落盘位置，漏一处就写进真实 `~/.dsh`。
 */
import { globSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";

import {
  CONFIG_FILE_NAME,
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  VERSION_FILE_NAME,
  legacyFile,
  notifierFile,
  toastScriptPath,
} from "../../../src/server/shared/interface.ts";
import { tempDshHome, withEnv } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原（漏一个就会污染后续用例的落盘位置）。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

describe("存储文件名即迁移契约", () => {
  it("五个文件名逐字固定", () => {
    expect([
      CONFIG_FILE_NAME,
      HISTORY_FILE_NAME,
      STATUS_FILE_NAME,
      SEQ_FILE_NAME,
      VERSION_FILE_NAME,
    ]).toEqual(["config.json", "history.jsonl", "status.json", "seq.json", "version"]);
  });

  it("插件私有目录按 npm 包名分区，不与其它插件争用 DSH home 根", () => {
    const home = tempDshHome();
    cleanups.push(home.dispose);
    expect(notifierFile(CONFIG_FILE_NAME)).toBe(
      join(home.dir, "@wingsky-1", "dsh-notifier", "config.json"),
    );
  });

  it("旧布局在 DSH home 根：迁移的读端与写端必须同时可命名，否则迁移会读空", () => {
    const home = tempDshHome();
    cleanups.push(home.dispose);
    expect(legacyFile("dsh-notifier.json")).toBe(join(home.dir, "dsh-notifier.json"));
  });
});

describe("DSH_HOME 语义（与 shared/dsh-home.js、官方 resolveDshHome 同源）", () => {
  it("空白 DSH_HOME 视同未设置，回落 <home>/.dsh", () => {
    // 两个 home 变量都设：POSIX 读 HOME，Windows 按 libuv 语义读 USERPROFILE。
    cleanups.push(
      withEnv({ DSH_HOME: "   ", HOME: "/dsh-home-probe", USERPROFILE: "/dsh-home-probe" }),
    );
    expect(notifierFile(VERSION_FILE_NAME)).toBe(
      join("/dsh-home-probe", ".dsh", "@wingsky-1", "dsh-notifier", "version"),
    );
  });
});

describe("系统通知脚本位置", () => {
  it("反推尾段与脚本在 src 下的真实位置一致（脚本搬家而函数没跟上即红）", () => {
    // 该函数按**包入口所在目录**反推：产物形态是内联的 lib/index.js，资源随 bundle-host 按
    // src 相对结构复制到 lib/ 下，故尾段必须等于脚本相对 src 的路径。断言「该路径存在」是假红
    // ——直跑 src 时包入口在 src 顶层，反推落点本就不存在；断言写死字面量则要人肉同步。
    const srcRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "src");
    const scripts = globSync("**/*.ps1", { cwd: srcRoot });
    expect(scripts).toHaveLength(1);
    expect(toastScriptPath().replaceAll("\\", "/").endsWith(`/${scripts[0]!}`)).toBe(true);
  });
});

packages/dsh-notifier/test/unit/api/jour.source:
/**
 * dsh-notifier api 域 journal 块 —— GET /history、DELETE /history、GET /status。
 *
 * 判据面：三个响应体的键名（`records` / `removed` / `channels`）是**客户端锁定**的契约，改一个名字
 * 页面就整块空白，而服务端不会有任何报错。另外这三个端点都必须**等**存储域的结果——store 的读是
 * 异步的，漏掉 await 会把一个 Promise 序列化成 `{}`，接口看上去「正常返回空历史」。
 */
import type { IncomingMessage } from "node:http";
import { describe, expect, it } from "vitest";

import type { StorePort } from "../../../src/server/api/deps.ts";
import { JournalEndpoints } from "../../../src/server/api/impl/journal/index.ts";
import { jsonReq, makeRes } from "../../helpers.ts";

const HISTORY = [
  { ts: 1, kind: "done", title: "第一条", message: "正文", channels: [] },
  { ts: 2, kind: "error", title: "第二条", message: "出错了" },
];

const STATUS = {
  "bark:main": {
    lastTs: 2,
    lastStatus: "failed" as const,
    // 0.2.4 起失败理由是结构化对象（#782 批 1）：`lastStatus` 与信封键名不变，只有这一项换了形态。
    lastError: { code: "reasonBarkHttp", params: { status: 500 } },
    failStreak: 3,
  },
};

/** 假请求：三个端点都不读 body，只有方法不同。 */
function makeReq(method: string): IncomingMessage {
  return jsonReq({ method, url: "/api/dsh-notifier/history" });
}

/** 假 stores 端口：三个读面各自回带标记的值。 */
function fakeStores() {
  const calls: string[] = [];
  const port: StorePort = {
    readHistory: async () => {
      calls.push("readHistory");
      return [...HISTORY];
    },
    clearHistory: async () => {
      calls.push("clearHistory");
      return 2;
    },
    readStatus: async () => {
      calls.push("readStatus");
      return { ...STATUS };
    },
  };
  return { port, calls };
}

describe("历史端点", () => {
  it("GET /history 回 `records`（键名是客户端锁定的契约，改名页面就整块空白）", async () => {
    const stores = fakeStores();
    const { res, rec, json } = makeRes();
    await new JournalEndpoints(stores.port).read(makeReq("GET"), res);
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true, records: HISTORY });
  });

  it("DELETE /history 回 `removed` 条数（页面据此提示清掉了几条）", async () => {
    const stores = fakeStores();
    const { res, rec, json } = makeRes();
    await new JournalEndpoints(stores.port).clear(makeReq("DELETE"), res);
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true, removed: 2 });
    expect(stores.calls).toEqual(["clearHistory"]);
  });
});

describe("频道状态端点", () => {
  it("GET /status 回 `channels`（含结构化失败理由与连续失败计数，设置页据此标记异常出口）", async () => {
    const stores = fakeStores();
    const { res, rec, json } = makeRes();
    await new JournalEndpoints(stores.port).readStatus(makeReq("GET"), res);
    expect(rec.status).toBe(200);
    // 信封与条目键集逐个钉死：`lastStatus` 仍是 `ok|failed` 二值，本版只把理由换成了结构化的
    expect(json()).toEqual({ ok: true, channels: STATUS });
    expect(stores.calls).toEqual(["readStatus"]);
  });
});

packages/dsh-notifier/test/unit/upgrade/.source:
/**
 * dsh-notifier upgrade 域 version 块 —— 存储刻度与版本比较。
 *
 * 判据面：刻度是「升级做到哪一步」的唯一凭证，读错一处就是整条链空转或永久停摆——而两者的外部表现
 * 与「版本没变」一模一样。版本比较必须**逐段按数值**：字符串比较会把 0.10.0 判成小于 0.9.0，
 * 于是新版本永远升不上去。
 */
import { readFileSync } from "node:fs";
import { afterEach, describe, expect, it } from "vitest";

import {
  VERSION_FILE_NAME,
  notifierFile,
  writeTextAtomicSync,
} from "../../../src/server/shared/interface.ts";
import {
  compareVersions,
  readStoredVersion,
  writeStoredVersion,
} from "../../../src/server/upgrade/impl/version/index.ts";
import { tempDshHome } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原并删除。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

/** 建一个隔离 DSH_HOME（刻度的读写都以它为根）。 */
function isolatedHome(): void {
  const home = tempDshHome();
  cleanups.push(home.dispose);
}

describe("compareVersions", () => {
  it.each<[string, string, number]>([
    ["0.2.3", "0.2.3", 0],
    ["0.2.4", "0.2.3", 1],
    ["0.2.3", "0.2.4", -1],
    ["0.10.0", "0.9.0", 1],
    ["0.3", "0.3.0", 0],
    // 段数不同时多余的段必须参与比较：只比到较短的那个，`0.2.4 > 0.2` 会被判成相等。
    ["0.2.4", "0.2", 1],
    ["1.0.0", "0.99.99", 1],
  ])("%s 与 %s 比较 → %i", (left, right, expected) => {
    expect(compareVersions(left, right)).toBe(expected);
  });
});

describe("刻度读写", () => {
  it("写进去再读回来是同一个版本号（刻度是纯文本一行，末尾换行不算内容）", () => {
    isolatedHome();
    expect(writeStoredVersion("0.2.4")).toEqual({ ok: true });
    expect(readStoredVersion()).toBe("0.2.4");
    expect(readFileSync(notifierFile(VERSION_FILE_NAME), "utf8")).toBe("0.2.4\n");
  });

  it("没有刻度文件时从 0.0.0 起算：从未升级过的安装要跑整条链（每步自己判断有没有活要干）", () => {
    isolatedHome();
    expect(readStoredVersion()).toBe("0.0.0");
  });

  it("空白刻度文件也算从未升级过（空串不能被当成一个版本号去比较）", () => {
    isolatedHome();
    writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), "  \n");
    expect(readStoredVersion()).toBe("0.0.0");
  });
});
